import React from "react"
import {
    SearchAutocomplete,
    type SearchAutocompleteItem,
} from "@/components/atoms/forms/SearchAutocomplete"

/**
 * `ConsultantDirectoryCompanySearch` ΓÇö a typed, debounced deep-link to one
 * recruiting company's page, sitting above the consultant grid on the directory
 * screen. It is not a grid filter: there is no server-side search over
 * consultants, only a company suggester, so it jumps straight to a known
 * company page. `isLoadingSuggestions` swaps the popover's content.
 */

/** One company the ES suggester matched against the typed query. */
export interface ConsultantCompanySuggestion {
    /** Stable company id ΓÇö the payload handed back through `onSelectCompany`. */
    id: string
    /** Company display name, already localized/formatted by the caller. */
    label: string
}

/** Props for {@link ConsultantDirectoryCompanySearch}. */
export interface ConsultantDirectoryCompanySearchProps {
    /** Current text in the search field (controlled). */
    query: string
    /** Fired with the new query on every keystroke; the screen owns debouncing. */
    onQueryChange: (value: string) => void
    /** Company matches for the current query, already fetched by the screen. */
    suggestions: Array<ConsultantCompanySuggestion>
    /** `true` while the screen is waiting on the ES company-suggester. */
    isLoadingSuggestions?: boolean
    /** Fired with the picked company's id; the screen owns the route push. */
    onSelectCompany: (companyId: string) => void
}

/**
 * The company deep-link search row atop the consultant directory. See the file
 * header for why this is a jump-to-company control and not a grid filter.
 *
 * @param props - {@link ConsultantDirectoryCompanySearchProps}
 */
const ConsultantDirectoryCompanySearch = ({
    query,
    onQueryChange,
    suggestions,
    isLoadingSuggestions = false,
    onSelectCompany,
}: ConsultantDirectoryCompanySearchProps) => {
    const items: Array<SearchAutocompleteItem> = suggestions.map((company) => ({
        id: company.id,
        label: company.label,
    }))

    // Sole root is SearchAutocomplete ΓÇö inert host wrappers removed. Identity
    // stays held until the atom accepts CallerIdentity (CourseTrialChip pattern).
    return (
        <SearchAutocomplete
            items={items}
            inputValue={query}
            onInputChange={onQueryChange}
            onSelect={onSelectCompany}
            isLoading={isLoadingSuggestions}
            // Owned wording: this field jumps to ONE company, it does not filter
            // the grid below it ΓÇö the placeholder has to say so or a visitor will
            // type a role/skill and get nothing back.
            placeholder="Search for a hiring company by nameΓÇª"
            emptyLabel="No companies found"
        />
    )
}

export { ConsultantDirectoryCompanySearch }

import React from "react"
import { AsyncContent, type AsyncContentEmptyProps } from "@/components/composites/async/AsyncContent"
import { Grid, type GridItem } from "@/components/frames/Grid"
import { StackV } from "@/components/frames/Stack"
import { Typography } from "@/components/atoms/text/Typography"
import { ConsultantCard, type ConsultantCardConsultant } from "@/components/blocks/consultant/ConsultantCard"

/**
 * `ConsultantDirectoryGrid` ΓÇö the consultant directory's browse surface: a
 * match count above the cards, across the loading ΓåÆ empty ΓåÆ content lifecycle.
 * `AsyncContent` owns the branch switch, `Grid` the responsive track,
 * `ConsultantCard` one tile. The count line renders inside the `content` branch
 * only, beside real cards.
 */

/** Props for {@link ConsultantDirectoryGrid}. */
export interface ConsultantDirectoryGridProps {
    /**
     * The current page's consultants, already sorted by the caller. `undefined`
     * ΓçÆ the list has not resolved yet (see {@link ConsultantDirectoryGridProps.isLoading}).
     */
    consultants?: Array<ConsultantCardConsultant>
    /**
     * How many consultants the directory lists in total. `undefined` ΓçÆ the
     * count line does not render yet (see file header's judgement call).
     */
    count?: number
    /**
     * `true` while the consultant list's own fetch has not resolved. Passed
     * straight to `AsyncContent` ΓÇö this block never infers it from
     * `consultants` itself (see file header).
     */
    isLoading: boolean
    /** Fired with a consultant's id when their card is pressed. */
    onOpenConsultant: (id: string) => void
    /** The empty-state message, already localized by the caller (see file header for why this stays a caller prop). */
    emptyTitle: string
    /** Accessible name for the directory region ΓÇö the block has no visible heading of its own. */
    ariaLabel: string
}

/** How many placeholder tiles mirror the grid while the list hasn't resolved ΓÇö ported from the real `ConsultantGrid`'s `SKELETON_COUNT`. */
const SKELETON_TILE_COUNT = 6

/** Skeleton tiles pass this as `onOpen` ΓÇö `ConsultantCard.isSkeleton` disables its own press, so it never fires. */
const NOOP = () => {}

/** The block's own wording for the count line (┬º14d.1) ΓÇö the caller only ever hands over a bare number. */
const countLabel = (count: number): string => `${count} consultants`

/**
 * The consultant directory's browse surface. See the file header for the full
 * contract and why the count line only shows beside real cards.
 *
 * @param props - {@link ConsultantDirectoryGridProps}
 */
const ConsultantDirectoryGrid = ({
    consultants,
    count,
    isLoading,
    onOpenConsultant,
    emptyTitle,
    ariaLabel,
}: ConsultantDirectoryGridProps) => {
    // Resolved-but-zero, matching the real `ConsultantGrid`'s Redux-driven gating
    // (`!consultants` = loading, `sortedConsultants.length === 0` = empty).
    const isEmpty = !isLoading && (consultants?.length ?? 0) === 0

    const skeletonTiles: Array<GridItem> = Array.from({ length: SKELETON_TILE_COUNT }, (_unused, index) => ({
        key: `skeleton-${index}`,
        content: () => (
            <ConsultantCard
                consultant={{ id: `skeleton-${index}`, fullName: "" }}
                onOpen={NOOP}
                isSkeleton
            />
        ),
    }))

    const tiles: Array<GridItem> = (consultants ?? []).map((consultant) => ({
        key: consultant.id,
        content: () => (
            <ConsultantCard
                consultant={consultant}
                onOpen={onOpenConsultant}
            />
        ),
    }))

    const emptyContent: AsyncContentEmptyProps = {
        title: emptyTitle,
    }

    return (
        <div role="region" aria-label={ariaLabel}>
            <AsyncContent
                isLoading={isLoading}
                skeleton={() => (
                    <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={skeletonTiles}  />
                )}
                isEmpty={isEmpty}
                emptyContent={emptyContent}
                content={() => (
                    <StackV gap={4} principle="group-boundary"
                        explain="Section group spacing ΓÇö not sibling-stack, because these blocks are distinct groups rather than same-kind peers."
                        items={[
                            ...(count !== undefined ? [() => (
                                <Typography size="sm" color="muted" text={countLabel(count)} />
                            )] : []),
                            () => (
                                <Grid columns={{ base: 1, sm: 2, lg: 3 }} principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={tiles}  />
                            ),
                        ]} />
                )}
            />
        </div>
    )
}

export { ConsultantDirectoryGrid }

import React from "react"
import { Breadcrumbs } from "@/components/atoms/navigation/Breadcrumbs"
import { PageHeader } from "@/components/composites/layout/Page"

/**
 * `ConsultantDirectoryHeader` ΓÇö the directory-identity cluster atop the
 * consultant directory screen: a course-scoped breadcrumb trail, a title, and an
 * optional one-line description. A thin `PageHeader` cluster with no read-state
 * chip or meta row. `description` is optional; `isSkeleton` swaps every atom for
 * its mirror. The breadcrumb trail always exists.
 */

/** One breadcrumb link ΓÇö plain data, the block builds the atom from it. */
export interface ConsultantDirectoryHeaderCrumb {
    /** Stable React key. */
    key: string
    /** Display label. */
    label: string
    /** Has a handler ΓåÆ the crumb is pressable; the current page leaves it out. */
    onPress?: () => void
}

/** Props for {@link ConsultantDirectoryHeader}. */
export interface ConsultantDirectoryHeaderProps {
    /** Breadcrumb trail as DATA ΓÇö the block builds `Breadcrumbs` itself (course ΓåÆ consultant directory). */
    breadcrumbItems?: Array<ConsultantDirectoryHeaderCrumb>
    /** Directory title. */
    title: string
    /** One-sentence summary of what the directory lists. */
    description?: string
    /**
     * `true` ΓåÆ every composed atom switches to its own shimmer. The flag FLOWS
     * DOWN into the real atoms rather than building a parallel skeleton tree
     * (┬º12c).
     */
    isSkeleton?: boolean
}

/**
 * The directory identity cluster at the top of the consultant directory
 * screen. See the file header for the full contract and why this is a thin
 * sibling of `ContentHeader`/`FoundationsHeader` rather than an edit of
 * either.
 *
 * @param props - {@link ConsultantDirectoryHeaderProps}
 */
const ConsultantDirectoryHeader = ({
    breadcrumbItems,
    title,
    description,
    isSkeleton = false,
}: ConsultantDirectoryHeaderProps) => {
    return (
        <div>
            <PageHeader

                isSkeleton={isSkeleton}
                breadcrumb={() =>
                    isSkeleton || breadcrumbItems?.length ? (
                        <div className="w-fit">
                            <Breadcrumbs
                                collapseOnMobile
                                collapseFrom={4}
                                items={breadcrumbItems ?? []}
                                isSkeleton={isSkeleton}
                            />
                        </div>
                    ) : undefined
                }
                title={title}
                description={description}
            />
        </div>
    )
}

export { ConsultantDirectoryHeader }

import React from "react"
import { BuildingsIcon, LockIcon } from "@phosphor-icons/react"
import { Image } from "@/components/atoms/media/Image"
import { Typography, type TypographyIcon } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Callout } from "@/components/composites/feedback/Callout"
import { StackV } from "@/components/frames/Stack"

/**
 * `ConsultantProfileBody` ΓÇö the full detail content of one consultant's profile:
 * photo, name+role, a pressable company row, the full bio, and either real
 * contact links once unlocked or a locked callout with a way to unlock them.
 * The detail sibling of `ConsultantCard`. `contactUnlocked` only changes which
 * content fills the last slot, not the outer frame.
 */

/** One way to reach this consultant once contact is unlocked ΓÇö plain navigable data. */
export interface ConsultantProfileBodyContactLink {
    /** Stable React key. */
    key: string
    /** Display label, e.g. "hoa.nguyen@techcorp.vn" or "090 123 4567". */
    label: string
    /** Where the link goes ΓÇö `mailto:`/`tel:`/`https:` etc. The atom renders it, never fetches it. */
    href: string
    /** Optional leading glyph (mail/phone/chat) as a COMPONENT, not JSX. */
    icon?: TypographyIcon
}

/** One consultant's full profile ΓÇö plain data, the block builds the detail view from it. */
export interface ConsultantProfileBodyConsultant {
    /** Full name ΓÇö the profile's accessible heading. */
    fullName: string
    /** Role/title at their company. Row disappears when absent. */
    jobTitle?: string
    /** Company name. The company row disappears when absent. */
    companyTitle?: string
    /** Full bio ΓÇö rendered in full here, unlike `ConsultantCard`'s clamped teaser. */
    description?: string
    /** Photo URL. Empty/missing ΓåÆ `Image`'s own fallback glyph, never a blank frame. */
    avatarUrl?: string
    /** `true` ΓåÆ real `contactLinks` are shown. `false` ΓåÆ the locked callout is shown instead. */
    contactUnlocked: boolean
    /** Ways to reach this consultant. Only read when `contactUnlocked` is `true`. */
    contactLinks?: Array<ConsultantProfileBodyContactLink>
}

/** Props for {@link ConsultantProfileBody}. */
export interface ConsultantProfileBodyProps {
    /** The consultant whose profile this fills. */
    consultant: ConsultantProfileBodyConsultant
    /** Fired when the visitor presses the company row. Row is disabled without it. */
    onOpenCompany?: () => void
    /** Fired from the locked callout's CTA. No CTA renders without it. */
    onImproveCv?: () => void
    /** Locked-callout heading. Falls back to the block's own English copy when omitted. */
    lockedTitle?: string
    /**
     * Locked-callout body ΓÇö the place to surface the required CV score (e.g.
     * "needs CV score >= 70"). Falls back to the block's own English copy when omitted.
     */
    lockedDescription?: string
    /** Locked-callout CTA label. Falls back to the block's own English copy when omitted. */
    lockedCtaLabel?: string
    /**
     * `true` ΓåÆ `Image` and every `Typography` line switch to their own shimmer, the
     * company button is disabled, and the contact fork shows a neutral shimmer
     * instead of picking a branch (see file header). There is no id to open yet.
     */
    isSkeleton?: boolean
}

/** Fixed copy for the locked-contact callout ΓÇö block-owned wording (┬º14d.1), see file header. */
const LOCKED_TITLE = "Contact is locked"
const LOCKED_DESCRIPTION = "Improve your CV to unlock this consultant's contact information."
const LOCKED_CTA_LABEL = "Improve CV"

/**
 * The full profile-detail content for one consultant. See the file header for
 * the full contract, the fork between `ConsultantCard`'s tile shape and this
 * one, and the judgment calls behind the contact fork.
 *
 * @param props - {@link ConsultantProfileBodyProps}
 */
const ConsultantProfileBody = ({
    consultant,
    onOpenCompany,
    onImproveCv,
    lockedTitle,
    lockedDescription,
    lockedCtaLabel,
    isSkeleton = false,
}: ConsultantProfileBodyProps) => {
    const { fullName, jobTitle, companyTitle, description, avatarUrl, contactUnlocked, contactLinks } = consultant

    const nameRow = (
        <StackV gap={1} align="center" principle="name-handle"
            explain="Display name with handle ΓÇö not title-subtitle, because the second line is an identity handle rather than a subtitle."
            isSkeleton={isSkeleton} items={[
                () => (
                    <Typography
                        size="h4"
                        weight="bold"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={fullName}

                    />
                ),
                ...(isSkeleton || jobTitle ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        align="center"
                        isSkeleton={isSkeleton}
                        text={jobTitle}

                    />
                )] : []),
            ]} />
    )

    // identity: centered photo, name+role, pressable company row
    const identity = (
        <StackV gap={4} align="center" principle="card-caption"
            explain="Holds caption text under card media so the caption stays attached to the image above it."
            isSkeleton={isSkeleton} items={[
                () => (
                    <div className="w-28">
                        <Image
                            src={avatarUrl}
                            alt={fullName}
                            ratio="square"
                            radius="full"
                            isSkeleton={isSkeleton}

                        />
                    </div>
                ),
                () => nameRow,
                ...(isSkeleton || companyTitle ? [() => (
                    <Button
                        isSkeleton={isSkeleton}
                        variant="secondary"
                        size="sm"
                        label={companyTitle ?? ""}
                        prefixIcon={BuildingsIcon}
                        onPress={onOpenCompany}
                        isDisabled={isSkeleton || !onOpenCompany}

                    />
                )] : []),
            ]} />
    )

    // contact fork ΓÇö see file header for why loading shimmers neutrally
    const contactFork = isSkeleton ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={[
            () => <Typography size="sm" isSkeleton />,
            () => <Typography size="sm" isSkeleton classNames={["w-1/3"]} />,
        ]} />
    ) : contactUnlocked ? (
        <StackV gap={2} isSkeleton={isSkeleton} items={(contactLinks ?? []).map((link) => () => (
            <Typography
                size="sm"
                isLink
                href={link.href}
                prefixIcon={link.icon}
                text={link.label}

            />
        ))} />
    ) : (
        <Callout
            status="warning"
            icon={LockIcon}
            title={lockedTitle ?? LOCKED_TITLE}
            description={lockedDescription ?? LOCKED_DESCRIPTION}
            actionLabel={onImproveCv ? (lockedCtaLabel ?? LOCKED_CTA_LABEL) : undefined}
            onAction={onImproveCv}


        />
    )

    return (
        <StackV
            gap={6}
            isSkeleton={isSkeleton}
            identity={{ tier: "block", component: "ConsultantProfileBody" }}
            items={[
                () => identity,
                // full bio ΓÇö no clamp, unlike ConsultantCard's directory teaser
                ...(isSkeleton || description ? [() => (
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}

                    />
                )] : []),
                () => contactFork,
            ]}
        />
    )
}

export { ConsultantProfileBody }

import React from "react"
import { Link } from "@heroui/react"
import { ArrowLeftIcon } from "@phosphor-icons/react"

/** Props for {@link _BackLink} ΓÇö presentational; the text already resolved. */
export interface BackLinkProps {
    /** Already-localized link text ("Back" / "Back to {target}" / a full override). */
    text: string
    /** Fired when the link is pressed ΓÇö the caller owns the routing. */
    onPress: () => void
}

/**
 * The single back affordance of a leaf / sub-view page ("ΓåÉ Back",
 * "ΓåÉ Back to challenge"ΓÇª), rendered top-left ΓÇö typically into `PageHeader`'s
 * `breadcrumb` slot. A quiet text link (muted), NOT a pill/button. Hover =
 * the arrow slides left + the label underlines (go-there affordance); the
 * block owns the look so every back link reads the same.
 *
 * @param props - {@link BackLinkProps}
 * @see Story: .storybook/stories/blocks/navigation/BackLink/BackLink.stories
 */
export const _BackLink = ({ text, onPress }: BackLinkProps) => (
    <Link
        onPress={onPress}
        className="group flex w-fit cursor-pointer items-center gap-2 text-sm text-muted no-underline transition-colors hover:text-foreground"
    >
        <ArrowLeftIcon
            aria-hidden
            focusable="false"
            className="size-4 transition-transform group-hover:-translate-x-1"
        />
        <span className="underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">{text}</span>
    </Link>
)

"use client"

import React from "react"
import {
    Typography,
    cn,
} from "@heroui/react"
import {
    CheckCircleIcon,
    CircleIcon,
    LockIcon,
    StarIcon,
} from "@phosphor-icons/react"
import type {
    ReactNode,
} from "react"
/** Props for the {@link ContentMapRow} block. */
export interface ContentMapRowProps {
    /** Lesson title (the row's accessible name). */
    title: string
    /** Highlights the row as the lesson currently open. */
    isActive: boolean
    /** Read (green check) ΓÇö highest-priority status marker. */
    isRead: boolean
    /** Locked (lock) ΓÇö the viewer cannot open it yet (no access). */
    isLocked?: boolean
    /** Premium / VIP (star) ΓÇö unlocked once enrolled; shown when not locked. */
    isPremium: boolean
    /** Optional right-aligned meta (e.g. the minutes-read label). */
    meta?: ReactNode
    /** Fired when the row is pressed (navigation handled by the caller). */
    onPress: () => void
}

/**
 * Single status marker per row, by priority: read ΓåÆ green check; locked ΓåÆ lock;
 * premium (accessible) ΓåÆ star; otherwise the plain "unread / reading" circle. Thin
 * outline icons (no fill weight); only the read state carries a (success) colour ΓÇö
 * the rest stay neutral/muted.
 */
const resolveStatus = ({ isRead, isLocked, isPremium }: Pick<ContentMapRowProps, "isRead" | "isLocked" | "isPremium">) => {
    if (isRead) {
        return { Icon: CheckCircleIcon, tone: "text-success-soft-foreground" }
    }
    if (isLocked) {
        return { Icon: LockIcon, tone: "text-foreground" }
    }
    if (isPremium) {
        return { Icon: StarIcon, tone: "text-foreground" }
    }
    return { Icon: CircleIcon, tone: "text-foreground" }
}

/**
 * A single compact lesson row for the course content-map rail: a read marker, the
 * title (two-line clamp), an optional premium lock, and right-aligned meta. The
 * whole row is one press target; the active lesson gets an accent tint. Pure +
 * props-only ΓÇö owns its look so features only compose it.
 *
 * @param props - {@link ContentMapRowProps}
 */
export const ContentMapRow = ({
    title,
    isActive,
    isRead,
    isLocked = false,
    isPremium,
    meta,
    onPress}: ContentMapRowProps) => {
    const { Icon, tone } = resolveStatus({ isRead, isLocked, isPremium })
    return (
        <button
            type="button"
            onClick={onPress}
            className={cn("flex w-full items-start gap-2 rounded-xl px-2 py-2 text-left transition-colors",
                isActive ? "bg-accent-soft" : "hover:bg-surface-secondary")}
        >
            {/* one thin status marker per row (read / locked / premium / unread) */}
            <Icon aria-hidden focusable="false" className={cn("mt-0 size-5 shrink-0", tone)} />
            <Typography
                type="body-sm"
                className={cn("line-clamp-2 min-w-0 flex-1", isActive && "text-accent-soft-foreground")}
            >
                {title}
            </Typography>
            {meta ? <span className="mt-0 shrink-0">{meta}</span> : null}
        </button>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { Tabs, cn } from "@heroui/react"

/** Props for the {@link ExtendedTabs} block. */
export interface ExtendedTabsProps {
    /** Currently selected tab id (controlled). */
    selectedKey: string
    /** Fired with the newly selected tab id. */
    onSelectionChange: (key: string) => void
    /**
     * Tab anatomy ΓÇö keep using the HeroUI compound parts inside:
     * `Tabs.ListContainer` > `Tabs.List` > `Tabs.Tab` (+ `Tabs.Indicator`).
     */
    children: ReactNode
    /**
     * HeroUI `Tabs` variant. `"secondary"` (default) = in-page CONTENT tabs ΓÇö
     * hugs its own label width (packs left, `.extended-tabs` override), no
     * outer baseline (the feature wrapper owns any full-width chrome; see
     * `TabsCard` ┬º1). `"primary"` = page-FEATURE tabs that switch the ENTIRE
     * panel content ΓÇö HeroUI's own default rendering (segmented pill,
     * full-width, evenly-stretched tabs), untouched by the `.extended-tabs`
     * hug-content override. Use `"primary"` for top-level section switches
     * (e.g. Begin/History/Stats), `"secondary"` for a content filter/
     * language-switcher riding alongside a reading column.
     */
    variant?: "primary" | "secondary"
    /**
     * `"md"` (default) = full-width (`w-full`), evenly-stretched tabs ΓÇö the
     * only size this block used to support. `"sm"` shrinks a `"primary"` tab
     * strip to `w-fit` (segments size to their label, don't stretch) ΓÇö for a
     * compact secondary choice that shouldn't claim the full row (e.g. a
     * setting nested inside a modal panel). Has no effect on `"secondary"`
     * (already hug-content via `.extended-tabs`).
     */
    size?: "sm" | "md"
}

/**
 * The StarCi standard tab strip: a thin wrapper over the HeroUI `Tabs` root.
 * `variant="secondary"` (default) bakes in the underline look ΓÇö foreground text
 * on the selected tab + an accent indicator ΓÇö and drops the built-in
 * `.tabs__list` baseline (so it never doubles up with an outer separator; see
 * `.extended-tabs` in globals.css). `variant="primary"` renders HeroUI's plain
 * default Tabs (full-width segmented pill) for page-level feature switches.
 * Drop-in replacement for `<Tabs>`; the children still use the `Tabs.*`
 * compound parts. Use this instead of styling `Tabs` per-feature.
 *
 * @param props - {@link ExtendedTabsProps}
 * @see Story: .storybook/stories/blocks/navigation/ExtendedTabs/ExtendedTabs.stories
 */
export const ExtendedTabs = ({
    selectedKey,
    onSelectionChange,
    children,
    variant = "secondary",
    size = "md"}: ExtendedTabsProps) => {
    return (
        <Tabs
            variant={variant}
            selectedKey={selectedKey}
            onSelectionChange={(key) => onSelectionChange(String(key))}
            className={cn(// tab labels must never wrap to a 2nd line ΓÇö white-space inherits down to
                // every Tabs.Tab, so a squeezed segment truncates (w-full) or sizes to the
                // one-line label (w-fit) instead of stacking words.
                "whitespace-nowrap",
                variant === "secondary" ? "extended-tabs" : size === "sm" ? "w-fit" : "w-full")}
        >
            {children}
        </Tabs>
    )
}

"use client"

import React from "react"
import type { ReactNode } from "react"
import { Button, ButtonGroup, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** One selectable button in a {@link FlexWrapButtonRadio}. */
export interface FlexWrapButtonRadioItem<T extends string> {
    /** Value selected when this button is chosen. */
    value: T
    /** Button content (icon + label + meta ΓÇö caller-defined inline row). */
    content: ReactNode
    /** When true the button is dimmed and not selectable. */
    isDisabled?: boolean
}

/** Props shared by both the single- and multi-select modes of {@link FlexWrapButtonRadio}. */
interface FlexWrapButtonRadioBaseProps<T extends string> extends WithClassNames<undefined> {
    /** The selectable buttons. */
    items: Array<FlexWrapButtonRadioItem<T>>
    /** Accessible label for the group. */
    ariaLabel: string
    /**
     * Optional trailing node placed after the buttons in the SAME row (e.g. a
     * "+N" overflow button). Not part of the group's value ΓÇö it's an action.
     */
    trailing?: ReactNode
    /**
     * Optional per-item trailing action(s) ΓÇö e.g. a delete button and/or a "..."
     * (kebab) menu trigger. When provided, the item's select button and these
     * action buttons render as ONE connected {@link ButtonGroup} per item
     * (`[select | delete | ...]`) ΓÇö touching, a full-height separator at every seam,
     * rounded only at the two outer ends ΓÇö instead of a detached button floating
     * beside the pill. Return the action `<Button>`s as an ARRAY (with `key`s) so
     * each is an individual segment the group can rounded/separate ΓÇö NOT wrapped in
     * a fragment (a fragment counts as one child and the per-button separator
     * injection would misfire). Omit for a plain single-select row (default ΓÇö
     * matches every existing caller's output). The actions are SIBLINGS of the
     * select button (a `<Button>` can't nest another interactive element), so a
     * click on one never changes the selection.
     */
    itemAction?: (item: FlexWrapButtonRadioItem<T>) => ReactNode
}

/** Single-select mode (default) ΓÇö exactly one value selected at a time. */
interface FlexWrapButtonRadioSingleProps<T extends string> extends FlexWrapButtonRadioBaseProps<T> {
    /** Single-select ΓÇö omit or pass `false`. */
    multiple?: false
    /** Currently selected value. */
    value: T
    /** Fired with the chosen value when a button is selected. */
    onChange: (value: T) => void
}

/**
 * Multi-select mode ΓÇö a SET of values, each button an independent toggle. The
 * caller owns the set + the toggle logic (e.g. enforcing "at least one selected");
 * this component only reports which button was pressed via {@link onToggle}.
 */
interface FlexWrapButtonRadioMultiProps<T extends string> extends FlexWrapButtonRadioBaseProps<T> {
    /** Multi-select ΓÇö pass `true`. */
    multiple: true
    /** Currently selected values. */
    values: Array<T>
    /** Fired with the pressed value (the caller adds/removes it from its own set). */
    onToggle: (value: T) => void
}

/** Props for the {@link FlexWrapButtonRadio} block ΓÇö a discriminated union on `multiple`. */
export type FlexWrapButtonRadioProps<T extends string> =
    | FlexWrapButtonRadioSingleProps<T>
    | FlexWrapButtonRadioMultiProps<T>

/**
 * A single-select toggle-button group laid out as a flex-wrap row (buttons wrap
 * to the next line, never scroll). Every option is a real HeroUI `<Button>`:
 * standalone, selected = filled `tertiary` (NEUTRAL, not accent ΓÇö a facet/config
 * toggle isn't a CTA), unselected = hollow `ghost` ΓÇö clean, no own surface (the
 * parent card, or the bare page, is the surface). NEVER `primary` here ΓÇö a config row commonly
 * sits on the SAME surface as the page's one accent CTA, and a solid-primary
 * selected pill would compete with it (1 accent-solid / surface, Von Restorff ΓÇö
 * `accent-system`).
 *
 * When `itemAction` is supplied, each item instead renders as one connected
 * {@link ButtonGroup} ΓÇö the select button + its action button(s) touching, only
 * the two outer ends rounded (`[select | delete | ...]`). No bordered frame: the button
 * VARIANTS carry the look ΓÇö EVERY segment is filled `--default` so the cluster
 * reads as one solid control (the select pill is `secondary` = default fill +
 * accent text when chosen, else `tertiary` = default fill + neutral text ΓÇö NOT a
 * hollow `ghost`, which would leave the unselected label floating on the page; the
 * action buttons are `tertiary` too). The seam is HeroUI's own
 * `ButtonGroup.Separator`, recoloured to the `--border` token (`!bg-border
 * !opacity-100`, overriding its default muddy `bg-current opacity-15`) so it
 * matches every other divider in the app. Because `.button` is
 * `position: relative`, the separator MUST live INSIDE the button that follows the
 * seam (its `left: -1px` then bites that button's left edge); so the component
 * injects one at the head of each action button's children ΓÇö callers just return
 * plain `<Button>`s. Overridden to FULL height (`!top-0 !h-full`) from HeroUI's
 * default 50%.
 *
 * `role="group"` + `aria-pressed` per button ΓÇö works for BOTH the default
 * single-select toggle group and the multi-select mode (`multiple`, a SET of
 * pressed toggles; the caller owns add/remove + any "keep ΓëÑ1 selected" rule). For
 * a grid with description/badge use `SelectableCardGroup`.
 *
 * @param props - {@link FlexWrapButtonRadioProps}
 * @see Story: .storybook/stories/blocks/navigation/FlexWrapButtonRadio/FlexWrapButtonRadio.stories
 */
export const FlexWrapButtonRadio = <T extends string>(props: FlexWrapButtonRadioProps<T>) => {
    const { items, ariaLabel, trailing, itemAction, className } = props
    // narrow the discriminated union once ΓÇö selection state + the press handler are
    // the only things that differ between single- and multi-select.
    const isSelected = (candidate: T): boolean =>
        (props.multiple ? props.values.includes(candidate) : props.value === candidate)
    const onItemPress = (candidate: T): void => {
        if (props.multiple) {
            props.onToggle(candidate)
        } else {
            props.onChange(candidate)
        }
    }
    return (
        <div role="group" aria-label={ariaLabel} className={cn("flex flex-wrap items-center gap-2", className)}>
            {items.map((item) => {
                const selected = isSelected(item.value)
                if (!itemAction) {
                    // standalone: selected = filled `tertiary` (neutral, NOT accent ΓÇö
                    // a facet toggle isn't a CTA), unselected = hollow `ghost` (no
                    // surface of its own ΓÇö the page/card is the surface).
                    return (
                        <Button
                            key={item.value}
                            size="sm"
                            variant={selected ? "tertiary" : "ghost"}
                            isDisabled={item.isDisabled}
                            aria-pressed={selected}
                            onPress={() => onItemPress(item.value)}
                        >
                            {item.content}
                        </Button>
                    )
                }
                // select button + its action(s) = ONE connected ButtonGroup per
                // item. No border frame ΓÇö the button variants carry the look; here
                // the unselected select is `tertiary` (filled `--default`), NOT
                // `ghost`, so it matches the filled action buttons instead of
                // floating hollow. Each action button gets a `ButtonGroup.Separator`
                // injected at the head of its children (HeroUI's separator must sit
                // INSIDE the following button ΓÇö see the class doc), full-height.
                return (
                    <ButtonGroup key={item.value} size="sm" className="w-fit">
                        <Button
                            size="sm"
                            variant={selected ? "secondary" : "tertiary"}
                            isDisabled={item.isDisabled}
                            aria-pressed={selected}
                            onPress={() => onItemPress(item.value)}
                        >
                            {item.content}
                        </Button>
                        {React.Children.map(itemAction(item), (action) =>
                            React.isValidElement<{ children?: ReactNode }>(action)
                                ? React.cloneElement(
                                    action,
                                    undefined,
                                    <ButtonGroup.Separator className="!top-0 !h-full !bg-border !opacity-100" />,
                                    action.props.children,
                                )
                                : action,
                        )}
                    </ButtonGroup>
                )
            })}
            {trailing}
        </div>
    )
}

"use client"

import React, {
    useEffect,
    useRef,
} from "react"
import type {
    ReactNode,
} from "react"
import {
    Accordion,
    Button,
    Input,
    Label,
    ScrollShadow,
    TextField,
    Typography,
    cn,
} from "@heroui/react"
import {
    ArrowRightIcon,
} from "@phosphor-icons/react"
import type {
    WithClassNames,
} from "@/modules/types/base/class-name"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { ContentMapRow } from "@/components/blocks/navigation/ContentMapRow"
import { ProgressMeter } from "@/components/composites/stats/ProgressMeter"

/**
 * Placeholder group count the co-located skeleton mirrors while `isSkeleton`
 * is set ΓÇö the real HeroUI `Accordion` and `ContentMapRow` below take no
 * `isSkeleton` of their own (missingSkeletonSupport), so this swaps in the
 * canonical `Skeleton.Accordion` piece right where the real tree sits.
 */
const SKELETON_GROUP_COUNT = 3

/** One selectable row inside an {@link OutlineRailGroup}. */
export interface OutlineRailItem {
    /** Stable id (accordion item key / scroll target). */
    id: string
    /** Row title (the row's accessible name). */
    title: string
    /** Highlights the row as the one currently open (accent tint). */
    isActive: boolean
    /** Read / completed ΓÇö green check, highest-priority marker. */
    isRead: boolean
    /** Locked ΓÇö the viewer cannot open it yet. */
    isLocked?: boolean
    /** Premium / VIP ΓÇö star (shown when not locked). */
    isPremium?: boolean
    /** Optional right-aligned meta (e.g. minutes, score). */
    meta?: ReactNode
    /** Fired when the row is pressed (navigation handled by the caller). */
    onPress: () => void
}

/** One collapsible group (module / milestone) of {@link OutlineRailItem}s. */
export interface OutlineRailGroup {
    /** Stable id used as the accordion key + expand state. */
    id: string
    /** Group title (truncated + native tooltip). */
    title: string
    /** Group progress ΓÇö expanded ΓåÆ a `ProgressMeter`; collapsed ΓåÆ {@link collapsedCountLabel}. */
    progress: { done: number; total: number }
    /** Pre-formatted "n/m" label shown when the group is collapsed. */
    collapsedCountLabel: string
    /** Rows in the group. */
    items: Array<OutlineRailItem>
}

/** The rail header ΓÇö the rail's progress + one primary action. */
export interface OutlineRailHeader {
    /** Label for the overall-progress row (e.g. "Progress"). */
    label: ReactNode
    /** Overall progress driving the header meter. */
    progress: { done: number; total: number }
    /** Pre-formatted overall count (e.g. "2/12 lessons"). */
    countLabel: ReactNode
    /** Optional primary "continue / resume" action. */
    continue?: { label: ReactNode; onPress: () => void }
}

/** Controlled search box state for the rail. */
export interface OutlineRailSearch {
    /** Current query. */
    value: string
    /** Query change handler. */
    onChange: (value: string) => void
    /** Placeholder text. */
    placeholder: string
    /** Accessible label. */
    ariaLabel: string
}

/**
 * The list region's error / empty wiring. The loading state is no longer
 * carried here ΓÇö it is the top-level {@link OutlineRailProps.isSkeleton},
 * which the list region mirrors co-located in place (no caller-supplied
 * `skeleton` tree).
 */
export interface OutlineRailAsync {
    /** Empty gate (no data at all). Ignored while {@link OutlineRailProps.isSkeleton} is set. */
    isEmpty: boolean
    /** Empty-state title. */
    emptyTitle: string
    /** Error-state title. */
    errorTitle: string
    /** Error to surface (prefer stale data once loaded; beats both skeleton and empty). */
    error?: unknown
    /** Retry handler. */
    onRetry: () => void
    /** Retry button label. */
    retryLabel: string
    /** Shown when a search filters everything out (groups present but empty). */
    noMatchLabel: string
}

/** Props for the {@link OutlineRail} block. */
export interface OutlineRailProps extends WithClassNames<undefined> {
    /** Progress header + continue action. Omit to hide the header (e.g. while loading). */
    header?: OutlineRailHeader
    /** Controlled search field. */
    search: OutlineRailSearch
    /** Ordered groups ΓåÆ rows. */
    groups: Array<OutlineRailGroup>
    /** Controlled expanded group ids. */
    expandedKeys: Set<string>
    /** Fires with the next expanded id set. */
    onExpandedChange: (keys: Set<string>) => void
    /**
     * First load, nothing in hand ΓåÆ the list region shimmers in place
     * (co-located: `Skeleton.Accordion` swaps in for the real `Accordion`
     * right where it sits ΓÇö `missingSkeletonSupport`, `loading-and-skeleton.md`).
     * Owned by the caller's first-load formula, e.g. `!data && !error`.
     */
    isSkeleton?: boolean
    /** Error / empty wiring for the list region. */
    async: OutlineRailAsync
}

/**
 * The shared docs-style navigation rail (UI 2.0): a pinned progress header with a
 * single "continue" action, a client-side search field, then a scroll region of
 * collapsible groups ΓåÆ compact {@link ContentMapRow} rows. One progress bar at a
 * time ΓÇö the open group shows a `ProgressMeter`, collapsed groups show a muted
 * "n/m" count.
 *
 * Props-only / fully controlled: the consuming feature owns the data, the search
 * value, the expanded-set (auto-open the active group, open matches on search),
 * and every string (i18n). Both the course content-map and the personal-project
 * milestone rail render through this one block, so they stay identical.
 *
 * Positioning (sticky / width / scroll height) is supplied by the caller via
 * `className`, so the same rail serves the desktop rail and the mobile drawer.
 *
 * @param props - {@link OutlineRailProps}
 * @see Story: .storybook/stories/blocks/navigation/OutlineRail/OutlineRail.stories
 */
export const OutlineRail = ({
    header,
    search,
    groups,
    expandedKeys,
    onExpandedChange,
    isSkeleton = false,
    async,
    className,
}: OutlineRailProps) => {
    /** Active row ΓÇö scrolled into view when it changes / the list hydrates. */
    const activeRowRef = useRef<HTMLDivElement>(null)
    const activeItemId = groups
        .flatMap((group) => group.items)
        .find((item) => item.isActive)?.id
    useEffect(() => {
        activeRowRef.current?.scrollIntoView({ block: "nearest" })
    }, [activeItemId])

    return (
        <div className={cn("relative flex min-h-0 min-w-0 flex-col gap-3 p-6", className)}>
            {/* progress header ΓÇö the "continue" action floats at the bottom (see below) */}
            {header ? (
                <div className="flex flex-col gap-2">
                    <div className="flex items-center justify-between gap-2">
                        <Label>{header.label}</Label>
                        <Typography type="body-xs" color="muted">
                            {header.countLabel}
                        </Typography>
                    </div>
                    <ProgressMeter value={header.progress.done} max={header.progress.total} />
                </div>
            ) : null}

            {/* client-side search over the visible tree */}
            <TextField>
                <Input
                    aria-label={search.ariaLabel}
                    value={search.value}
                    onChange={(event) => search.onChange(event.target.value)}
                    placeholder={search.placeholder}
                />
            </TextField>

            {/* only the list scrolls ΓÇö soft fade, header + search stay pinned. Extra bottom
                padding when the floating action is present so the last row clears it. */}
            <ScrollShadow hideScrollBar className={cn("-mx-1 min-h-0 min-w-0 flex-1 overflow-x-hidden overflow-y-auto px-1", header?.continue && "pb-20")}>
                {/* error beats a stale skeleton flag; empty only once settled (loading-and-skeleton.md ┬º1) */}
                {async.error ? (
                    <AsyncContentError
                        title={async.errorTitle}
                        onRetry={async.onRetry}
                        retryLabel={async.retryLabel}
                    />
                ) : !isSkeleton && async.isEmpty ? (
                    <AsyncContentEmpty title={async.emptyTitle} />
                ) : isSkeleton ? (
                    // the real `Accordion` (HeroUI) and `ContentMapRow` below take no `isSkeleton`
                    // of their own ΓÇö mirrored right here with the canonical `Skeleton.Accordion`
                    // piece instead of a caller-supplied parallel skeleton tree (missingSkeletonSupport).
                    <Skeleton.Accordion className="w-full" items={SKELETON_GROUP_COUNT} />
                ) : groups.length > 0 ? (
                    <Accordion
                        variant="default"
                        className="min-w-0 w-full"
                        expandedKeys={expandedKeys}
                        onExpandedChange={(keys) => onExpandedChange(new Set([...keys].map(String)))}
                    >
                        {groups.map((group) => {
                            const isExpanded = expandedKeys.has(group.id)
                            return (
                                <Accordion.Item
                                    key={group.id}
                                    id={group.id}
                                    aria-label={group.title}
                                    className="min-w-0"
                                >
                                    <Accordion.Heading className="min-w-0">
                                        <Accordion.Trigger className="min-w-0 w-full max-w-full px-0 py-2 hover:bg-transparent">
                                            {/* title truncates to one line; count/bar on the line below */}
                                            <div className="flex w-full min-w-0 items-center gap-2 overflow-hidden">
                                                <div className="flex min-w-0 flex-1 flex-col overflow-hidden">
                                                    <Typography
                                                        type="body"
                                                        weight="semibold"
                                                        truncate
                                                        title={group.title}
                                                        className="w-full min-w-0"
                                                    >
                                                        {group.title}
                                                    </Typography>
                                                    {isExpanded ? (
                                                        <ProgressMeter
                                                            value={group.progress.done}
                                                            max={group.progress.total || 1}
                                                        />
                                                    ) : (
                                                        <Typography type="body-xs" color="muted">
                                                            {group.collapsedCountLabel}
                                                        </Typography>
                                                    )}
                                                </div>
                                                <Accordion.Indicator className="shrink-0" />
                                            </div>
                                        </Accordion.Trigger>
                                    </Accordion.Heading>
                                    <Accordion.Panel>
                                        <Accordion.Body className="px-0 pb-3">
                                            <div className="flex flex-col gap-0">
                                                {group.items.map((item) => (
                                                    <div
                                                        key={item.id}
                                                        ref={item.isActive ? activeRowRef : undefined}
                                                    >
                                                        <ContentMapRow
                                                            title={item.title}
                                                            isActive={item.isActive}
                                                            isRead={item.isRead}
                                                            isLocked={item.isLocked}
                                                            isPremium={item.isPremium ?? false}
                                                            onPress={item.onPress}
                                                            meta={item.meta}
                                                        />
                                                    </div>
                                                ))}
                                            </div>
                                        </Accordion.Body>
                                    </Accordion.Panel>
                                </Accordion.Item>
                            )
                        })}
                    </Accordion>
                ) : (
                    <Typography type="body-sm" color="muted" align="center">
                        {async.noMatchLabel}
                    </Typography>
                )}
            </ScrollShadow>

            {/* the rail's one primary action ΓÇö a frosted bottom bar so it stays reachable
                while the list scrolls behind it (was a static top button). The bar (px-6 py-3)
                is a click-through blur layer; only the full-width button catches the press. */}
            {header?.continue ? (
                <div className="pointer-events-none absolute inset-x-0 bottom-0 bg-background/80 px-6 py-3 backdrop-blur-md">
                    <Button
                        variant="primary"
                        size="lg"
                        onPress={header.continue.onPress}
                        className="pointer-events-auto w-full"
                    >
                        {header.continue.label}
                        <ArrowRightIcon aria-hidden focusable="false" className="size-5" />
                    </Button>
                </div>
            ) : null}
        </div>
    )
}

export default OutlineRail

import React, { useCallback, useMemo } from "react"
import { Pagination as HeroPagination, cn } from "@heroui/react"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link _Pagination} ΓÇö presentational; every aria-label already resolved. */
export interface PaginationProps extends WithClassNames<undefined> {
    /** 1-based current page. */
    currentPage: number
    /** Total number of pages (>= 1). */
    totalPages: number
    /** Fired with a 1-based page number when the user changes page. */
    onPageChange: (pageNumber: number) => void
    /** Already-localized aria-label for the pagination nav landmark. */
    navAriaLabel: string
    /** Already-localized "Previous page" aria-label. */
    previousAriaLabel: string
    /** Already-localized "Next page" aria-label. */
    nextAriaLabel: string
}

/**
 * Generic, reusable page-based pagination control.
 *
 * Presentational + controlled: renders page links + prev/next from the supplied
 * page state and delegates navigation via `onPageChange`. The parent owns paging
 * (client-side or server-driven), so this stays reusable across any list.
 *
 * @param props - {@link PaginationProps}
 * @see Story: .storybook/stories/blocks/navigation/Pagination/Pagination.stories
 */
export const _Pagination = ({
    currentPage,
    totalPages,
    onPageChange,
    navAriaLabel,
    previousAriaLabel,
    nextAriaLabel,
    className,
}: PaginationProps) => {
    /** All 1-based page numbers to render (lists using this control are small). */
    const pageNumbers = useMemo(
        () => Array.from({ length: totalPages }, (_, index) => index + 1),
        [totalPages],
    )

    /** Go to the previous page, clamped to the first page. */
    const onPrevious = useCallback(
        () => onPageChange(Math.max(1, currentPage - 1)),
        [currentPage, onPageChange],
    )

    /** Go to the next page, clamped to the last page. */
    const onNext = useCallback(
        () => onPageChange(Math.min(totalPages, currentPage + 1)),
        [currentPage, totalPages, onPageChange],
    )

    return (
        <div className={cn("mt-6 flex justify-center", className)}>
            <HeroPagination aria-label={navAriaLabel} size="sm">
                <HeroPagination.Content className="flex flex-wrap justify-center gap-1">
                    <HeroPagination.Item>
                        <HeroPagination.Previous
                            aria-label={previousAriaLabel}
                            isDisabled={currentPage <= 1}
                            onPress={onPrevious}
                        >
                            <HeroPagination.PreviousIcon />
                        </HeroPagination.Previous>
                    </HeroPagination.Item>
                    {pageNumbers.map((pageNumber) => (
                        <PaginationLink
                            key={pageNumber}
                            pageNumber={pageNumber}
                            isActive={pageNumber === currentPage}
                            onPageChange={onPageChange}
                        />
                    ))}
                    <HeroPagination.Item>
                        <HeroPagination.Next
                            aria-label={nextAriaLabel}
                            isDisabled={currentPage >= totalPages}
                            onPress={onNext}
                        >
                            <HeroPagination.NextIcon />
                        </HeroPagination.Next>
                    </HeroPagination.Item>
                </HeroPagination.Content>
            </HeroPagination>
        </div>
    )
}

/** Props for {@link PaginationLink}. */
interface PaginationLinkProps {
    /** 1-based page number this link targets. */
    pageNumber: number
    /** Whether this link is the active page. */
    isActive: boolean
    /** Fired with this link's page number on press. */
    onPageChange: (pageNumber: number) => void
}

/**
 * A single page link; isolates its press handler so no inline arrow lives in the map.
 *
 * @param props - {@link PaginationLinkProps}
 */
const PaginationLink = ({
    pageNumber,
    isActive,
    onPageChange,
}: PaginationLinkProps) => {
    /** Navigate to this link's page. */
    const onPress = useCallback(
        () => onPageChange(pageNumber),
        [pageNumber, onPageChange],
    )
    return (
        <HeroPagination.Item>
            <HeroPagination.Link isActive={isActive} onPress={onPress}>
                {pageNumber}
            </HeroPagination.Link>
        </HeroPagination.Item>
    )
}

import React from "react"
import {
    CodeIcon,
    FileTextIcon,
    HouseIcon,
    PulseIcon,
    PuzzlePieceIcon,
    RocketIcon,
} from "@phosphor-icons/react"
import {
    TabsExtended,
    TabsIndicator,
    TabsList,
    TabsListContainer,
    TabsTab,
    type IconComponent,
} from "@/components/atoms/navigation/Tabs"
import { Typography } from "@/components/atoms/text/Typography"
import { StackH } from "@/components/frames/Stack"

/**
 * `ProfileTabsBar` ΓÇö the public-profile route strip (overview / projects /
 * challenges / skills / cv / activity). Draws the already-gated tab list the
 * caller hands it and reports a pick back via `onTabChange`; visibility gating
 * stays upstream. Uses `TabsExtended` (composing the `Tabs.*` children
 * directly) so one region (icon) can stay visible while another (label + owner
 * marker) drops below `@app-md`. One leaf: which tabs show, which is active,
 * and which carries the "┬╖ hidden" marker are data.
 */

/** Every public-profile destination this strip can offer ΓÇö ported from the real `ProfileTab`. */
export type ProfileTab = "overview" | "projects" | "challenges" | "skills" | "cv" | "activity"

/** Tab ΓåÆ label. Block-owned wording (┬º14d.1), ported verbatim from `publicProfile.tabs.*`. */
const TAB_LABEL: Record<ProfileTab, string> = {
    overview: "Overview",
    projects: "Projects",
    challenges: "Challenges",
    skills: "Skills",
    cv: "CV",
    activity: "Activity",
}

/** Tab ΓåÆ icon. Ported 1:1 from the real `TAB_ICONS` table. */
const TAB_ICON: Record<ProfileTab, IconComponent> = {
    overview: HouseIcon,
    projects: RocketIcon,
    challenges: PuzzlePieceIcon,
    skills: CodeIcon,
    cv: FileTextIcon,
    activity: PulseIcon,
}

/**
 * Glyph scale for a `text-sm` (14px) label ΓÇö same ┬º5a pairing `TabsBase` already
 * uses for its own icon column, ported here since this block hand-composes the
 * tab's inside instead of going through that atom's `items`.
 */
const TAB_ICON_CLASS = "size-3.5"
const TAB_ICON_WEIGHT = "bold" as const

/** The owner-only marker riding beside a hidden section tab's label. */
const HIDDEN_MARKER = "┬╖ hidden"

/** Props for {@link ProfileTabsBar}. */
export interface ProfileTabsBarProps {
    /** Which destination's route is being viewed now. */
    activeTab: ProfileTab
    /**
     * Destinations to render, in display order ΓÇö ALREADY gated by the caller
     * (owner sees every tab; a visitor never receives a tab their
     * `sectionVisibility`/`hasPublicCv` withheld). This block draws exactly this
     * list, nothing more.
     */
    visibleTabs: ReadonlyArray<ProfileTab>
    /** Fired with the tab the visitor picked. The screen decides how to navigate. */
    onTabChange: (tab: ProfileTab) => void
    /**
     * Section tabs (a subset of {@link visibleTabs}) the OWNER has switched off
     * for other visitors ΓÇö rendered with a "┬╖ hidden" marker beside the label so the
     * owner can tell at a glance. Omit (or leave empty) for a visitor's own view.
     */
    hiddenTabs?: ReadonlyArray<ProfileTab>
    /** Accessible name for the tab list, localized by the caller (blocks carry no i18n). */
    ariaLabel: string
}

/**
 * The profile's route-derived tab strip. See the file header for why the gating
 * computation and routing stay out of this block, and why `TabsExtended` (not
 * `TabsBase`) composes it.
 *
 * @param props - {@link ProfileTabsBarProps}
 */
const ProfileTabsBar = ({
    activeTab,
    visibleTabs,
    onTabChange,
    hiddenTabs,
    ariaLabel,
}: ProfileTabsBarProps) => {
    // TabsExtended size md already owns full-width stretch ΓÇö no wrapper host.
    return (
        <TabsExtended
            selectedKey={activeTab}
            onSelectionChange={(key) => onTabChange(key as ProfileTab)}
        >
            <TabsListContainer>
                <TabsList aria-label={ariaLabel}>
                    {visibleTabs.map((tabId) => {
                        const Icon = TAB_ICON[tabId]
                        const isHidden = hiddenTabs?.includes(tabId) ?? false
                        return (
                            <TabsTab
                                key={tabId}
                                id={tabId}
                            >
                                <StackH
                                    gap={2}
                                    principle="icon-text"
                                    explain="Icon beside its label ΓÇö not name-handle, because this pairs a glyph with text rather than a name/handle identity."
                                    align="center"
                                    items={[
                                        () => <Icon aria-hidden focusable="false" className={TAB_ICON_CLASS} weight={TAB_ICON_WEIGHT} />,
                                        // Icon-only below @app-md ΓÇö label (and its marker) only
                                        // from a tablet-wide profile strip up.
                                        () => (
                                            <span className="hidden @app-md:inline">
                                                <Typography size="sm" text={TAB_LABEL[tabId]} />
                                                {isHidden ? (
                                                    <>
                                                        {" "}
                                                        <Typography size="sm" color="muted" text={HIDDEN_MARKER} />
                                                    </>
                                                ) : null}
                                            </span>
                                        ),
                                    ]}
                                />
                                <TabsIndicator />
                            </TabsTab>
                        )
                    })}
                </TabsList>
            </TabsListContainer>
        </TabsExtended>
    )
}

