/**
 * A {@link import("../SidebarNavItem").SidebarNavItem}-weight sidebar row that
 * expands in place to a short list of child destinations, instead of routing
 * directly ΓÇö for a small fixed cluster of related surfaces (e.g. the
 * Playground's Docker/Kubernetes/RAG exercises) that doesn't warrant its own
 * flat rows cluttering the nav. Built on HeroUI `Accordion` (`variant="default"`
 * ΓÇö it sits directly on the sidebar's own background, not a card surface, per
 * `fe/components/accordion.md` ┬º3 "pick the skin based on the background context"), single item,
 * closed by default.
 *
 * @param props - {@link SidebarNavAccordionGroupProps}
 * @see Story: .storybook/stories/blocks/navigation/SidebarNavAccordionGroup/SidebarNavAccordionGroup.stories
 */
export const SidebarNavAccordionGroup = ({
    icon: Icon,
    label,
    items}: SidebarNavAccordionGroupProps) => {
    // collapsed rail (icon-only) has no room for a panel ΓÇö fall back to the
