                                            : "text-foreground hover:bg-default/40",
                                    )}
                                >
                                    <Typography
                                        type="body-sm"
                                        className={cn("min-w-0 flex-1", child.isActive ? "text-accent-soft-foreground" : undefined)}
                                        weight={child.isActive ? "medium" : "normal"}
                                        truncate
                                    >
                                        {child.label}
                                    </Typography>
                                </Link>
                            ))}
                        </Accordion.Body>
                    </Accordion.Panel>
                ) : null}
            </Accordion.Item>
        </Accordion>
    )
