/** A controlled group of secondary tabs ΓÇö one side of a {@link TabsCard}. */
export interface TabsCardGroup {
    /** Tabs in display order. */
    items: Array<TabsCardItem>
    /** Currently selected tab key. */
    selectedKey: string
    /** Accessible name for this group's tab list. */
    ariaLabel: string
    /** Fired with the newly selected tab key. */
    onSelectionChange: (key: Key) => void
}

/** Props for the {@link TabsCard} block. */
export interface TabsCardProps extends WithClassNames<undefined> {
    /** Primary tab group, pinned left. */
    leftTabs: TabsCardGroup
    /**
     * Inline cluster rendered right AFTER the left tab group ΓÇö actions that belong
     * to the left axis (e.g. a manage-menu for the active tab, an "+" add button,
     * an overflow count). Rendered as SIBLINGS of the tab list, never inside a
     * `Tabs.Tab` (react-aria tabs can't nest interactive elements).
     */
    leftEnd?: ReactNode
    /** Optional secondary tab group, pinned right (e.g. a language switcher). */
    rightTabs?: TabsCardGroup
    /**
     * Collapse `rightTabs` into a compact dropdown below `sm` (mobile), expanding
     * back to inline tabs from `sm` up. Use when the right group is a set-once
     * preference (e.g. the language switcher) that would crowd a narrow reading
     * column. Defaults to inline at every width.
     */
    collapseRightOnMobile?: boolean
    /**
     * Render `rightTabs` with NEUTRAL selected chrome (foreground underline) instead
     * of accent. Use when the right group is a "same content, different presentation"
     * toggle (e.g. the language switcher) ΓÇö only the primary `leftTabs` group should
     * carry the accent, so the toolbar has one accent signal, not two. Defaults to
     * accent (both groups accent).
     */
    rightTabsNeutral?: boolean
    /**
     * `"secondary"` (default) = in-page content tabs ΓÇö underline, hugs its own
     * label width, no outer baseline (this component's caller owns full-width
     * chrome if it wants any, ┬º1). `"primary"` = page-FEATURE tabs that switch
     * the ENTIRE panel content ΓÇö full-width, evenly-stretched segmented pill
     * (HeroUI's own default Tabs look). Use `"primary"` for top-level section
     * switches (e.g. Start/History/Statistics), `"secondary"` for a content
     * filter/language-switcher. Applies to BOTH groups (a toolbar is either
     * page-feature nav or in-page filter nav, not a mix).
     */
    variant?: "primary" | "secondary"
    /**
     * `"md"` (default) = full-width `"primary"` tabs (unchanged). `"sm"`
     * shrinks BOTH groups to a compact `w-fit` strip with smaller
     * padding/text ΓÇö for a `"primary"` choice that's a secondary/nested
     * setting, not a top-level page switch (e.g. a toggle inside a modal
     * panel). No effect on `"secondary"` (already hug-content).
     */
    size?: "sm" | "md"
}

/** size -> extra Tab className override (md = HeroUI's own default, no override). */
const TAB_SIZE_SM = "h-auto! w-auto! px-3! py-2! text-xs!"

/**
 * Selected-state TEXT color only (accent tab group) ΓÇö the underline itself now
 * comes from `<Tabs.Indicator/>` (native HeroUI `.tabs--secondary` accent bar).
 * Corrected 2026-07-09: this used to ALSO draw its own manual `border-b-2
 * border-accent`, which ΓÇö once `<Tabs.Indicator/>` was added per tabs.md ┬º5 ΓÇö
 * doubled up with the indicator's own bottom line under the same tab.
 */
const TAB_CLASS_ACCENT = "rounded-none data-[selected=true]:text-accent-soft-foreground"

/**
 * Selected-state chrome ΓÇö NEUTRAL foreground underline (secondary toggle
 * group, no accent). Kept on the MANUAL `border-b-2` technique (unlike
 * `TAB_CLASS_ACCENT` above) because `.tabs--secondary`'s indicator is
 * hardcoded `bg-accent` ΓÇö there is no "neutral-colored" native indicator to
 * switch to, so `<Tabs.Indicator/>` is suppressed for this path (see below).
 */
const TAB_CLASS_NEUTRAL =
    "rounded-none data-[selected=true]:border-b-2 data-[selected=true]:border-foreground data-[selected=true]:font-medium data-[selected=true]:text-foreground"

/**
 * Two secondary (underline) tab groups sharing one toolbar row: `leftTabs` pinned
 * left, optional `rightTabs` pinned right, a `gap-3` gutter between them. Both sides
 * use the same secondary chrome (no primary), so the row reads as one nav layer ΓÇö
 * e.g. content tabs on the left and a language switcher on the right. Pass each side
 * as data (items + selectedKey + onSelectionChange); the block owns all styling.
 *
 * @param props - {@link TabsCardProps}
 * @see Story: .storybook/stories/blocks/navigation/TabsCard/TabsCard.stories
 */
export const TabsCard = ({
    leftTabs,
    leftEnd,
    rightTabs,
    collapseRightOnMobile,
    rightTabsNeutral,
    variant = "secondary",
    size = "md",
    className,
}: TabsCardProps) => {
    /** Render one controlled tab group (`accent` = accent selected chrome, secondary-only). */
    const renderGroup = (group: TabsCardGroup, accent = true): ReactNode => (
        <ExtendedTabs
            variant={variant}
            size={size}
            selectedKey={group.selectedKey}
            onSelectionChange={group.onSelectionChange}
        >
            <Tabs.ListContainer>
                <Tabs.List aria-label={group.ariaLabel}>
                    {group.items.map((item) => (
                        <Tabs.Tab
                            key={item.key}
                            id={item.key}
                            isDisabled={item.isDisabled}
                            className={cn(
                                variant === "secondary" && (accent ? TAB_CLASS_ACCENT : TAB_CLASS_NEUTRAL),
                                size === "sm" && TAB_SIZE_SM,
                                item.muted && "text-muted",
                            )}
                        >
                            <span className="flex items-center gap-2">
                                {item.icon}
                                {/* a tab WITH an icon hides its label visually on mobile
                                    (icon-only) and shows it from sm up; `sr-only` keeps the
                                    accessible name on mobile. An icon-less tab always shows it. */}
                                {item.label ? (
                                    <span className={cn(item.icon && "sr-only @app-sm:not-sr-only")}>
                                        {item.label}
                                    </span>
                                ) : null}
                            </span>
                            {/* REQUIRED for "primary" and secondary-ACCENT (fe/components/tabs.md
                                ┬º5) ΓÇö HeroUI Tabs renders no selected-state chrome of its own;
                                without this, "primary" reads as plain undifferentiated text (no
                                floating pill) and secondary-accent has no underline at all.
                                Suppressed for secondary-NEUTRAL: `.tabs--secondary`'s indicator is
                                hardcoded `bg-accent` (no neutral color option), so that path keeps
                                its OWN `border-b-2 border-foreground` (TAB_CLASS_NEUTRAL) as the
                                sole indicator instead of doubling up with a wrong-colored one. */}
                            {(variant === "primary" || accent) && <Tabs.Indicator />}
                        </Tabs.Tab>
                    ))}
                </Tabs.List>
            </Tabs.ListContainer>
            {/* react-aria's useTab ALWAYS computes an `aria-controls` id pointing at
                a tabpanel with this tab's key, whether or not one is ever rendered
                (no console warning fires ΓÇö see fe review 2026-07-14). Without this,
                the selected tab's `aria-controls` dangles at a non-existent element,
                an axe-core/Lighthouse-flagged a11y bug. `TabsCard` never shows panel
                CONTENT here (callers render their own content elsewhere), so these
                panels stay empty/`sr-only` ΓÇö they exist purely to satisfy the
                tab<->tabpanel ARIA relationship. */}
            {group.items.map((item) => (
                <Tabs.Panel key={item.key} id={item.key} className="sr-only">{null}</Tabs.Panel>
            ))}
        </ExtendedTabs>
    )

    /**
     * Render `group` as a compact single-select dropdown ΓÇö the mobile form of a
     * set-once right group (e.g. the language switcher) so it never crowds the row.
     */
    const renderSelect = (group: TabsCardGroup): ReactNode => {
        const selected = group.items.find((item) => item.key === group.selectedKey)
        return (
            <Select.Root<{ id: string }, "single">
                variant="secondary"
                aria-label={group.ariaLabel}
                selectedKey={group.selectedKey}
                onSelectionChange={(key) => {
                    if (key !== null) {
                        group.onSelectionChange(key)
                    }
                }}
            >
                <Select.Trigger aria-label={group.ariaLabel}>
                    <Select.Value>
                        {() => (
                            <span className="flex items-center">
                                {selected?.icon}
                                {/* trigger is icon-only to stay compact; keep the
                                    selected option's name for screen readers */}
                                <span className="sr-only">{selected?.label}</span>
                            </span>
                        )}
                    </Select.Value>
                    <Select.Indicator />
                </Select.Trigger>
                <Select.Popover>
                    <ListBox.Root aria-label={group.ariaLabel}>
                        {group.items.map((item) => (
                            <ListBox.Item
                                key={item.key}
                                id={item.key}
                                isDisabled={item.isDisabled}
                                textValue={
                                    typeof item.label === "string" ? item.label : item.key
                                }
                            >
                                <span className="flex items-center gap-2">
                                    {item.icon}
                                    {item.label}
                                </span>
                            </ListBox.Item>
                        ))}
                    </ListBox.Root>
                </Select.Popover>
            </Select.Root>
        )
    }

    return (
        <div className={cn("flex items-center justify-between gap-3", className)}>
            {leftEnd ? (
                <div className="flex min-w-0 items-center gap-1">
                    {renderGroup(leftTabs)}
                    {leftEnd}
                </div>
            ) : renderGroup(leftTabs)}
            {rightTabs
                ? collapseRightOnMobile
                    ? (
                        <>
                            {/* mobile: collapse to a dropdown; sm+: inline tabs */}
                            <div className="@app-sm:hidden">{renderSelect(rightTabs)}</div>
                            <div className="hidden @app-sm:block">{renderGroup(rightTabs, !rightTabsNeutral)}</div>
                        </>
                    )
                    : renderGroup(rightTabs, !rightTabsNeutral)
                : null}
        </div>
    )
}

import React from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Chip } from "@/components/atoms/chips/Chip"
import { Typography } from "@/components/atoms/text/Typography"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { StackH, StackV } from "@/components/frames/Stack"

/**
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * STORYBOOK-LOCAL DESIGN SPEC ΓÇö `Page.*`, the ONE page-chrome frame namespace
 * (teacher's call, 2026-07-25, canon ┬º13a). Sibling frames that used to live as loose
 * folders (`PageHeader` ┬╖ `StickyBottomBar`) are now MEMBERS of one namespace
 * ΓÇö same tier (frame / layout), same family (chrome of a ROUTE: what sits above
 * the content and pinned under it), one import.
 *
 * FRAME API LAW (┬º13b):
 * - `PageBottomBar` is a WRAPPER frame -> named slots `body`/`actions` (a bar
 *   is a horizontal row, so `header`/`footer` would be a lie).
 * - `PageHeader` is NOT a generic wrapper ΓÇö it already owns semantic slots
 *   (`breadcrumb`/`title`/`description`/`actions`/`meta`) and deliberately
 *   takes no `children`.
 * - No repeating list here, so no `items` member (┬º13b list clause N/A).
 * - Namespace only ΓÇö no bare component export.
 *
 * Behaviour/skin of every member is carried over VERBATIM from its old folder;
 * this is an API refactor, not a visual one. Synced to `src` later. No
 * `@/components` imports (design-spec ports stay self-contained).
 *
 * HISTORY ΓÇö `.Container` was moved to `Container` (`@/components/frames/Container/Container`)
 * on 2026-07-26: the old frame had no `mx-auto`, no `max-w`, only right padding ΓÇö
 * a half-baked version of the "content width" concept that `Container` already
 * does correctly (┬º13c: a duplicate frame gets deleted).
 *
 * COMPOSITE-8 ΓÇö both `PageHeader` and `PageBottomBar` own an `isSkeleton` of
 * their own, so every slot they render is a COMPONENT reference
 * (`ComponentType<{ isSkeleton?: boolean }>`), never a pre-built node: the
 * frame calls it itself so it can forward `isSkeleton` into it. Text the
 * frame renders directly through `Typography` (`title`/`description`) is a
 * plain `string` instead ΓÇö the frame wraps it in the atom itself.
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 */

/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Page" } as const

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// .Header ΓÇö the breadcrumb/title/description/actions/meta block (was `PageHeader`)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** Props {@link PageHeader} carries regardless of loading state. */
interface PageHeaderOwnProps {

    /**
     * Optional supporting description placed directly below the title. The
     * frame renders it through `Typography` itself (`text-sm`, muted tone) and
     * forwards `isSkeleton`, so this is plain text (COMPOSITE-8), not a
     * pre-built node. Omit when the title is self-explanatory.
     */
    description?: string
    /**
     * Optional breadcrumb row rendered above the title row, as a COMPONENT
     * reference (COMPOSITE-8) ΓÇö the frame calls it itself. Typically a
     * `<Breadcrumbs>` house atom or a `LinkBack`. Omitted entirely while
     * loading (a route rarely needs it before data lands).
     */
    breadcrumb?: ComponentTypeWithSkeleton
    /**
     * Optional right-aligned slot for action controls, as a COMPONENT
     * reference ΓÇö the frame calls it and renders it `shrink-0` so it never
     * compresses the title column. Omitted entirely while loading.
     */
    actions?: ComponentTypeWithSkeleton
    /**
     * Optional meta row placed BELOW the title/description ΓÇö typically a row
     * of stat/meta chips ("24 Modules ┬╖ 87 Content items ΓÇª") ΓÇö as a
     * COMPONENT reference. Rendered `gap-3` from the title block. While
     * loading, the frame draws its OWN 2-chip placeholder instead of calling
     * this (COMPOSITE-10: the frame decides how many, not this slot). Omit
     * when the header carries no stats.
     */
    meta?: ComponentTypeWithSkeleton
    /**
     * Title scale. `"page"` (default) = `Typography.Heading` level 3 ΓÇö a route's
     * OWN page title. `"compact"` = body-size bold, for a header that labels a
     * PANE/PHASE inside an existing page shell.
     */
    size?: "page" | "compact"
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Props for {@link PageHeader}. `title` is REQUIRED unless `isSkeleton` (┬º12b) ΓÇö
 * a shimmer header has no real title to show yet.
 */
export type PageHeaderProps = PageHeaderOwnProps &
    (
        | {
            isSkeleton: true
            /** Primary page or section title. See the live variant's doc for the full contract. */
            title?: string
        }
        | {
            isSkeleton?: false
            /**
             * Primary page or section title. Rendered at `text-xl font-medium` in the
             * foreground tone through `Typography` (COMPOSITE-8: the frame builds it
             * itself, so this is plain text).
             */
            title: string
        }
    )

/**
 * Page/section header frame. Renders an optional breadcrumb row above a flex
 * row that places a stacked title + description on the left and optional action
 * controls on the right.
 *
 * This frame carries no card wrapper ΓÇö the caller places it directly inside
 * a `Container` or wraps it in a `SectionCard` when a framed surface
 * is required.
 *
 * @param props - See {@link PageHeaderProps}.
 */
const Header = ({
    title,
    description,
    breadcrumb: Breadcrumb,
    actions: Actions,
    meta: Meta,
    size = "page",
    isSkeleton = false,
    classNames}: PageHeaderProps) => {
    // ONE render path (┬º12c) ΓÇö every part this frame would render anyway stays,
    // each handed `isSkeleton`; the atoms draw their own shimmer. While loading, the
    // real shape (breadcrumb/description/meta presence) isn't known yet, so the
    // composite makes the same shape call the old hand-split branch made: assume a
    // description line and a 2-chip meta row, skip breadcrumb/actions (a route
    // rarely needs those before data lands).
    const showDescription = isSkeleton || description != null
    const showMeta = isSkeleton || Meta != null

    // Left column: stacked title and optional description
    const titleBlock = (
        <>
            {size === "compact" ? (
                <Typography weight="bold" isSkeleton={isSkeleton} text={title} />
            ) : (
                <Typography size="h3" weight="bold" isSkeleton={isSkeleton} text={title} />
            )}
            {showDescription ? (
                // clamp to 2 lines on mobile (keep the header short on a phone); full on sm+
                // ΓÇö a viewport-width decision, so the wrapper owns it, not the atom.
                <div className={isSkeleton ? undefined : "line-clamp-2 @app-sm:line-clamp-none"}>
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}
                    />
                </div>
            ) : null}
        </>
    )
    // Main row: title+description stack on the left, actions pinned to the right
    const titleRow = (
        <StackH
            align="start"
            justify="between"
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            items={[
                () => <StackV gap={3} classNames={["min-w-0"]} items={[() => titleBlock]} />,
                // Right slot: shrink-0 prevents action buttons from being squeezed.
                // Omitted while loading ΓÇö the shape of the action row isn't known yet.
                ...(!isSkeleton && Actions ? [() => (
                    <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>
                )] : []),
            ]}
        />
    )
    const headerBody = (
        <>
            {/* Breadcrumb row ΓÇö rendered only when provided and loaded, sits above the main title row */}
            {!isSkeleton && Breadcrumb ? (
                <div><Breadcrumb isSkeleton={isSkeleton} /></div>
            ) : null}
            {titleRow}
            {/* Meta row: stat/meta chips below the title block (gap={4} from outer). While
                loading, 2 `Chip` placeholders stand in ΓÇö the composite decides the count,
                the atom draws its own pill shimmer (no hand-rolled bar). */}
            {showMeta ? (
                isSkeleton ? (
                    <StackH
                        gap={3}
                        align="stretch"
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        items={[
                            () => <Chip isSkeleton />,
                            () => <Chip isSkeleton />,
                        ]}
                    />
                ) : (
                    <div>{Meta ? <Meta isSkeleton={isSkeleton} /> : null}</div>
                )
            ) : null}
        </>
    )
    return (
        // outer gap={4}: breadcrumb <-> title-block <-> meta (different header tiers);
        // title <-> description stay a related gap={3} pair inside the title block.
        <StackV gap={4} classNames={classNames} items={[() => headerBody]} />
    )
}

