/** Props for {@link PageBottomBar}. */
export interface PageBottomBarProps {
    /**
     * Leading content of the bar ΓÇö typically a price ΓÇö as a COMPONENT
     * reference (COMPOSITE-8): the frame calls it itself so it can forward
     * `isSkeleton`.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Trailing control(s) ΓÇö the primary CTA ΓÇö as a COMPONENT reference. When
     * BOTH `body` and `actions` are given the frame lays out the row itself
     * (`justify-between`, `shrink-0` on the actions) so callers stop
     * hand-rolling that flex row.
     */
    actions?: ComponentTypeWithSkeleton
    /** Shorthand for {@link PageBottomBarProps.body} ΓÇö same component-reference contract. */
    /**
     * `true` -> forwarded into whichever of `body`/`actions` renders, so a bar
     * whose price/CTA is not known yet (e.g. still loading enrollment status)
     * can shimmer instead of showing stale content.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * A fixed bottom action bar pinned to the viewport edge ΓÇö owns the chrome
 * (fixed position, top divider, surface background, safe padding) so features
 * just drop a price + CTA inside. Typically `@app-md:hidden` for a mobile sticky
 * enroll/checkout bar.
 *
 * A bar is a horizontal row, so its named slots are `body` (leading) +
 * `actions` (trailing) rather than the vertical `header`/`body`/`footer` trio.
 * With only one of them the content renders RAW, so a full-width button or a
 * two-button decision row keeps its own sizing (`flex-1`, `w-full`).
 *
 * @param props - {@link PageBottomBarProps}
 */
const BottomBar = ({
    body,
    actions,
    isSkeleton = false,
    classNames}: PageBottomBarProps) => {
    const Main = body
    const Actions = actions
    const chrome = "fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 border-t border-separator bg-background px-6 py-3"

    // Only ONE side supplied -> render it raw: the caller's own width strategy
    // (`w-full` CTA, two `flex-1` buttons) must not be boxed by a shrink-0 wrapper.
    if (Main == null || Actions == null) {
        const Only = Main ?? Actions
        return (
            <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
                <div>{Only ? <Only isSkeleton={isSkeleton} /> : null}</div>
            </div>
        )
    }

    return (
        <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
            <StackH
                align="center"
                justify="between"
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => <div className="min-w-0"><Main isSkeleton={isSkeleton} /></div>,
                    () => <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>,
                ]}
            />
        </div>
    )
}

/**
 * Page chrome members ΓÇö a route imports these by name:
 *
 * | Export | Content channel |
 * |---|---|
 * | `PageHeader` | `breadcrumb`/`title`/`description`/`actions`/`meta` (no children) |
 * | `PageBottomBar` | `body`/`actions` slots |
 *
 * `.Container` moved to `Container` (`@/components/frames/Container/Container`)
 * on 2026-07-26 ΓÇö see the history note at the top of this file.
 */
export { Header as PageHeader, BottomBar as PageBottomBar }

"use client"

import React from "react"
import { Chip, cn } from "@heroui/react"
import { useTranslations } from "next-intl"
import { CATEGORY_COLOR } from "@/modules/utils/blog-category"
import { BlogCategory } from "@/modules/api/graphql/queries/types/blog"
import { Cluster } from "@/components/frames/Cluster"

/** Props for {@link CategoryFilter}. */
export interface CategoryFilterProps {
    /** Active pillar (`null` = "All"). */
    value: BlogCategory | null
    /** Called when the reader picks a different pillar. */
    onChange: (next: BlogCategory | null) => void
    /**
     * Pillars that actually have posts (excluding `null`). The row renders `All`
     * + these only ΓÇö never a filter pointing at an empty bucket. The caller hides
     * the whole row when fewer than two pillars exist.
     */
    categories: Array<BlogCategory>
}

/**
 * Editorial-pillar filter row. Each pillar is a `cursor-pointer` chip button with
 * a hover affordance; the active one is filled, the rest soft. Controlled ΓÇö the
 * container owns the selected value + data fetch + which pillars are available.
 */
export const CategoryFilter = ({ value, onChange, categories }: CategoryFilterProps) => {
    const t = useTranslations("blog")
    const filters: Array<BlogCategory | null> = [null, ...categories]
    return (
        <div role="group" aria-label={t("title")}>
            <Cluster
                gap={3}
                principle="chip-row"
                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                items={filters.map((filter) => {
                    const selected = filter === value
                    return () => (
                        <button
                            key={filter ?? "all"}
                            type="button"
                            onClick={() => onChange(filter)}
                            aria-pressed={selected}
                            className="cursor-pointer rounded-full outline-none focus-visible:ring-2 focus-visible:ring-accent"
                        >
                            <Chip
                                size="md"
                                variant={selected ? "primary" : "soft"}
                                color={filter ? CATEGORY_COLOR[filter] : "accent"}
                                className={cn(
                                    !selected && "opacity-75 transition-opacity hover:opacity-100",
                                )}
                            >
                                {filter ? t(`categories.${filter}`) : t("categories.all")}
                            </Chip>
                        </button>
                    )
                })}
            />
        </div>
    )
}

"use client"

import React from "react"
import { useTranslations } from "next-intl"
import { Chip } from "@/components/atoms/chips/Chip"
import { Link } from "@/i18n/navigation"
import { CATEGORY_COLOR } from "@/modules/utils/blog-category"
import { type QueryBlogPostListItem } from "@/modules/api/graphql/queries/types/blog"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link FeaturedPost}. */
export interface FeaturedPostProps {
    /** The newest post, given the editorial-lead treatment. */
    post: QueryBlogPostListItem
    /** Localized, preformatted publish date (the caller owns locale formatting). */
    formattedDate: string
}

/**
 * The editorial lead ΓÇö the newest post rendered flat (no card) with a serif
 * display title so it anchors the page even when only a few posts exist. The
 * cover is shown only when present (most posts have none ΓåÆ typography leads).
 */
export const FeaturedPost = ({ post, formattedDate }: FeaturedPostProps) => {
    const t = useTranslations("blog")
    const readingMinutes = post.readingMinutes
    return (
        <Link
            href={`/blog/${post.slug}`}
            className="group cursor-pointer border-b border-default pb-6"
        >
            <StackV gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                // eyebrow: pillar chip ┬╖ "latest" ┬╖ optional premium
                    () => (
                        <Cluster gap={3} principle="chip-row"
                            explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                            items={[
                                () => (
                                    <Chip tone={CATEGORY_COLOR[post.category]} text={t(`categories.${post.category}`)} />
                                ),
                                () => (
                                    <span className="text-xs font-medium text-accent-soft-foreground">
                                        {t("latest")}
                                    </span>
                                ),
                                ...(post.isPremium ? [() => (
                                    <Chip tone="warning" text={t("premium")} />
                                )] : []),
                            ]} />
                    ),

                    // optional cover ΓÇö only when the post actually has one
                    () => (post.coverImageUrl ? (
                        <img
                            src={post.coverImageUrl}
                            alt=""
                            className="aspect-[16/9] w-full rounded-large object-cover"
                        />
                    ) : null),

                    // serif display title ΓÇö the page's visual hero
                    () => (
                        <h2 className="text-3xl font-semibold leading-tight text-foreground underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                            {post.title}
                        </h2>
                    ),
                    () => (post.excerpt ? <p className="text-base text-muted">{post.excerpt}</p> : null),

                    () => (
                        <StackH gap={3} principle="identity" align="center"
                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                            items={[
                                () => <span className="text-sm text-muted">{formattedDate}</span>,
                                ...(readingMinutes != null ? [
                                    () => <span aria-hidden className="text-sm text-muted">┬╖</span>,
                                    () => <span className="text-sm text-muted">{t("readingMinutes", { minutes: readingMinutes })}</span>,
                                ] : []),
                            ]} />
                    ),
                ]} />
        </Link>
    )
}

"use client"

