const ArchitectureScene = dynamic(
    () => import("@/components/blocks/marketing/ArchitectureScene").then((m) => m.ArchitectureScene),
    {
        ssr: false,
        loading: () => (
            <div
                aria-hidden
                className="h-[440px] w-full animate-pulse rounded-3xl bg-default/20 @app-sm:h-[560px]"
            />
        ),
