    notFound: string
    /** Error-state title on a settled fetch failure. */
    error: string
    /** Retry button label (paired with `onRetry`). */
    retry: string
    /** "Description" section heading. */
    descriptionLabel: string
    /** "Requirements" section heading. */
    requirementsLabel: string
    /** Expired-posting callout message. */
    expired: string
    /** Primary "Apply" CTA label (external-URL apply method). */
    apply: string
    /** "Apply via <email>" CTA label, already interpolated with the address ΓÇö only meaningful when `canApplyByEmail`. */
    applyByEmail?: string
}

/** Props for {@link _JobDetailPage} ΓÇö presentational; all data resolved, no fetch/store/i18n. */
export interface JobDetailPageProps {
    /** First load, nothing in hand ΓåÆ the whole tree shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with no posting for the given `displayId` ΓåÆ the not-found empty message. */
    isEmpty?: boolean
    /** Truthy ΓåÆ the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler ΓÇö paired with `labels.retry` to show a retry button on the error branch. */
    onRetry?: () => void
    /** Posting title. */
    title?: string
    /** Already-translated work-mode label (e.g. "Remote") ΓÇö omitted when the posting carries no work mode. */
    workModeLabel?: string
    /** Already-translated employment-type label (e.g. "Full-time") ΓÇö omitted when absent. */
    employmentTypeLabel?: string
    /** Free-text location ΓÇö omitted when absent. */
    location?: string
    /** Already-translated "Posted X ago" sentence. */
    postedAgoLabel?: string
    /** The posting company. */
    company?: JobDetailCompany
    /** Already-formatted salary label (a range, a single figure, or "Negotiable"). */
    salaryLabel?: string
    /** Markdown job description. */
    description?: string
    /** Optional markdown requirements/qualifications. */
    requirements?: string
    /** `true` ΓåÆ the posting is past `expiresAt`; the Apply CTA is replaced with a closed-notice callout. */
    expired?: boolean
    /** `true` ΓåÆ the external-URL Apply CTA renders (posting's `applyMethod` is `ExternalUrl` and carries a URL). */
    canApplyExternal?: boolean
    /** `true` ΓåÆ the email Apply CTA renders (posting's `applyMethod` is `Email` and carries an address). */
    canApplyByEmail?: boolean
    /** Opens `applyUrl` in a new tab ΓÇö only meaningful with `canApplyExternal`. */
    onApplyExternal?: () => void
    /** Hands off to the OS mail client ΓÇö only meaningful with `canApplyByEmail`. */
    onApplyByEmail?: () => void
    labels: JobDetailLabels
}

/**
 * "Meta" chip/text row under the title: work-mode chip, employment-type chip, location, and
 * "posted X ago" ΓÇö each shown only when its data resolved, EXCEPT while `isSkeleton`, when all
 * four render as generic placeholders (real shape unknown yet, so a plausible full row shimmers).
 */
const buildMetaItems = ({
    isSkeleton,
    workModeLabel,
    employmentTypeLabel,
    location,
    postedAgoLabel,
}: Pick<JobDetailPageProps, "isSkeleton" | "workModeLabel" | "employmentTypeLabel" | "location" | "postedAgoLabel">): Array<ComponentTypeWithSkeleton> => {
    if (isSkeleton) {
        return [
            () => <Chip tone="default" isSkeleton />,
            () => <Chip tone="accent" isSkeleton />,
            () => <Typography size="sm" color="muted" isSkeleton />,
        ]
    }
    return [
        ...(workModeLabel ? [() => <Chip tone="default" text={workModeLabel} />] : []),
        ...(employmentTypeLabel ? [() => <Chip tone="accent" text={employmentTypeLabel} />] : []),
        ...(location ? [() => <Typography size="sm" color="muted" prefixIcon={MapPinIcon} text={location} />] : []),
        ...(postedAgoLabel ? [() => <Typography size="sm" color="muted" text={postedAgoLabel} />] : []),
    ]
}

/**
 * `_JobDetailPage` ΓÇö the presentational half of {@link import("./index").JobDetailPage}: full posting
 * (title, company, markdown description + requirements, salary, work-mode/employment-type chips)
 * and the apply CTA. Four states in the fixed order error ΓåÆ skeleton ΓåÆ empty ΓåÆ content
 * (`loading-and-skeleton.md`): `error` falls to the shared `AsyncContentError` frame, `isEmpty`
 * to `AsyncContentEmpty`, and otherwise the ONE tree renders with `isSkeleton` threaded to every
 * leaf that supports it. `PageHeader`/`IconTile`/`MarkdownContent` carry no `isSkeleton` prop of
 * their own, so their loading state is mirrored in place with `Skeleton.*` right where each sits.
 * See `tiers/split.md` ΓÇö the connected `index.tsx` owns the fetch and i18n.
 *
 * @param props - {@link JobDetailPageProps}
 */
export const _JobDetailPage = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    title,
    workModeLabel,
    employmentTypeLabel,
    location,
    postedAgoLabel,
    company,
    salaryLabel,
    description,
    requirements,
    expired = false,
    canApplyExternal = false,
    canApplyByEmail = false,
    onApplyExternal,
    onApplyByEmail,
    labels,
}: JobDetailPageProps) => {
    // error beats a stale loading flag; empty only once settled (loading-and-skeleton.md ┬º1)
    if (error) {
        return <AsyncContentError title={labels.error} onRetry={onRetry} retryLabel={labels.retry} />
    }
    if (!isSkeleton && isEmpty) {
        return <AsyncContentEmpty icon={BriefcaseIcon} title={labels.notFound} />
    }

    const metaItems = buildMetaItems({ isSkeleton, workModeLabel, employmentTypeLabel, location, postedAgoLabel })
    const showRequirements = isSkeleton || Boolean(requirements)
    const showCompanyDescription = isSkeleton || Boolean(company?.description)

    return (
        <Container
            body={() => (
                <StackV
                    gap={8}
                    items={[
                        // Title + meta chip row ΓÇö PageHeader has no isSkeleton of its own, so its
                        // title slot is fed a co-located Skeleton.Typography while loading.
                        () => (
                            <PageHeader
                                title={isSkeleton ? <Skeleton.Typography type="h3" width="2/3" /> : title}
                                meta={<Cluster gap={3} items={metaItems} />}
                            />
                        ),

                        // Company card ΓÇö logo tile (no isSkeleton of its own, mirrored in place),
                        // name (linked to the company page when resolvable), description, salary.
                        () => (
                            <SurfaceCard
                                body={() => (
                                    <StackH
                                        gap={3}
                                        principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        items={[
                                            () => (isSkeleton ? (
                                                <Skeleton className="size-16 shrink-0 rounded-2xl" />
                                            ) : (
                                                <IconTile
                                                    icon={<BuildingsIcon aria-hidden focusable="false" />}
                                                    src={company?.logoUrl}
                                                    alt={company?.title}
                                                    tone="neutral"
                                                    size="md"
                                                />
                                            )),
                                            () => {
                                                const companyHref = !isSkeleton ? company?.href : undefined
                                                return (
                                                    <StackV
                                                        gap={1}
                                                        classNames={["min-w-0", "flex-1"]}
                                                        items={[
                                                            () => (companyHref ? (
                                                                <Typography
                                                                    size="base"
                                                                    weight="semibold"
                                                                    isLink
                                                                    href={companyHref}
                                                                    underlineOnHover
                                                                    color="default"
                                                                    text={company?.title ?? ""}
                                                                />
                                                            ) : (
                                                                <Typography size="base" weight="semibold" isSkeleton={isSkeleton} text={company?.title ?? ""} />
                                                            )),
                                                            ...(showCompanyDescription ? [() => (
                                                                <Typography size="sm" color="muted" lineClamp={2} isSkeleton={isSkeleton} text={company?.description ?? ""} />
                                                            )] : []),
                                                        ]}
                                                    />
                                                )
                                            },
                                            () => <Typography size="h4" weight="bold" classNames={["shrink-0"]} isSkeleton={isSkeleton} text={salaryLabel ?? ""} />,
                                        ]}
                                    />
                                )}
                            />
                        ),

                        // Description + optional requirements ΓÇö MarkdownContent has no isSkeleton of
                        // its own, so its loading state is a co-located Skeleton.Paragraph.
                        () => (
                            <StackV
                                gap={6}
                                items={[
                                    () => (
                                        <StackV
                                            gap={2}
                                            items={[
                                                () => <Typography size="base" weight="semibold" isSkeleton={isSkeleton} text={labels.descriptionLabel} />,
                                                () => (isSkeleton
                                                    ? <Skeleton.Paragraph lines={DESCRIPTION_SKELETON_LINES} />
                                                    : <MarkdownContent markdown={description ?? ""} />),
                                            ]}
                                        />
                                    ),
                                    ...(showRequirements ? [() => (
                                        <StackV
                                            gap={2}
                                            items={[
                                                () => <Typography size="base" weight="semibold" isSkeleton={isSkeleton} text={labels.requirementsLabel} />,
                                                () => (isSkeleton
                                                    ? <Skeleton.Paragraph lines={REQUIREMENTS_SKELETON_LINES} />
                                                    : <MarkdownContent markdown={requirements ?? ""} />),
                                            ]}
                                        />
                                    )] : []),
                                ]}
                            />
                        ),

                        // Apply CTA ΓÇö a closed-notice callout once expired, otherwise the one CTA the
                        // posting's applyMethod resolves to. A generic button shimmer while loading,
                        // since expiry/method aren't known yet.
                        () => {
                            if (isSkeleton) {
                                return <Button isSkeleton size="lg" />
                            }
                            if (expired) {
                                return <Callout status="warning" title={labels.expired} />
                            }
                            if (canApplyExternal) {
                                return <Button variant="primary" size="lg" label={labels.apply} suffixIcon={ArrowRightIcon} onPress={onApplyExternal} />
                            }
                            if (canApplyByEmail && labels.applyByEmail) {
                                return <Button variant="primary" size="lg" label={labels.applyByEmail} suffixIcon={ArrowRightIcon} onPress={onApplyByEmail} />
                            }
                            return null
                        },
                    ]}
                />
            )}
        />
    )
}

"use client"

import React, {
    useMemo,
} from "react"
import {
    Button,
    Typography,
} from "@heroui/react"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import {
    BookOpenIcon,
    FlagIcon,
    PuzzlePieceIcon,
} from "@phosphor-icons/react"
import {
    formatDateTime,
    getTimeAgoLabel,
    getTimeAgoMessage,
} from "@/modules/dayjs"
import { toDifficulty } from "@/modules/utils/difficulty"
import { CourseLearningEventType } from "@/modules/api/graphql/queries/types/course-learning-history"
import type { CourseLearningHistoryItemData } from "@/modules/api/graphql/queries/types/course-learning-history"
import { useQueryCourseLearningHistorySwr } from "@/hooks/swr/api/graphql/queries/useQueryCourseLearningHistorySwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { AsyncContentEmpty } from "@/components/composites/async/AsyncContent"
import { DifficultyChip } from "@/components/blocks/chips/DifficultyChip"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { ListRow } from "@/components/blocks/lists/ListRow"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { StackV } from "@/components/frames/Stack"

/** Props for {@link CourseDayTimeline}. */
export interface CourseDayTimelineProps {
    /** Selected course RELAY GLOBAL ID (the `?course=` value, passed to the query). */
    courseGlobalId: string
    /** Lower-cased trimmed search query; filters events by label, client-side. */
    query: string
}

/** Event-type ΓåÆ entity icon (phosphor `*Icon`) shown as the row's leading tile. */
const EVENT_ICON: Record<CourseLearningEventType, typeof BookOpenIcon> = {
    [CourseLearningEventType.LessonRead]: BookOpenIcon,
    [CourseLearningEventType.ChallengePassed]: PuzzlePieceIcon,
    [CourseLearningEventType.MilestonePassed]: FlagIcon,
}

/** Event-type ΓåÆ IconTile tone. */
const EVENT_TONE = {
    [CourseLearningEventType.LessonRead]: "accent",
    [CourseLearningEventType.ChallengePassed]: "success",
    [CourseLearningEventType.MilestonePassed]: "warning",
} as const

/** A day bucket of learning events under a relative day header. */
interface DayGroup {
    /** Stable key (start-of-day ms as string). */
    key: string
    /** Header label ("Today" / "Yesterday" / a formatted date). */
    label: string
    /** Events in this day, newest first. */
    items: Array<CourseLearningHistoryItemData>
}

/** Start-of-day epoch ms for a date (local). */
const startOfDayMs = (date: Date): number =>
    new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime()

/**
 * "By day" view ΓÇö the viewer's per-course learning journal: every
 * `lessonRead` / `challengePassed` / `milestonePassed` event, newest first,
 * grouped under relative day headers (Today / Yesterday / localized date). Each
 * row is an entity-icon tile + the label + a module/type subtitle + an optional
 * {@link DifficultyChip} + a relative timestamp. Drives its own cursor-paginated
 * SWR (load more) and filters by the shared search query, client-side. Every
 * data state goes through {@link AsyncContent}; empties center.
 *
 * @param props - {@link CourseDayTimelineProps}
 */
export const CourseDayTimeline = ({
    courseGlobalId,
    query}: CourseDayTimelineProps) => {
    const t = useTranslations()
    const locale = useLocale()
    const {
        data,
        size,
        setSize,
        isLoading,
        isValidating,
        error,
        mutate,
    } = useQueryCourseLearningHistorySwr(courseGlobalId)

    // flatten every loaded page into one newest-first list
    const items = useMemo(
        () => (data ?? []).flatMap((page) => page.items),
        [data],
    )
    const hasMore = Boolean(data && data.length > 0 && data[data.length - 1].nextCursor !== null)
    const isLoadingMore = isValidating && Boolean(data) && size > 0

    // search filters loaded events by label, client-side
    const filtered = useMemo(
        () => (query ? items.filter((item) => item.label.toLowerCase().includes(query)) : items),
        [items, query],
    )

    // bucket the filtered events by local day
    const dayGroups = useMemo<Array<DayGroup>>(
        () => {
            const now = new Date()
            const todayMs = startOfDayMs(now)
            const dayMs = 86_400_000
            const groups: Array<DayGroup> = []
            for (const item of filtered) {
                const at = new Date(item.at)
                const dayMsValue = startOfDayMs(at)
                let label: string
                if (dayMsValue === todayMs) {
                    label = t("profileSettings.learning.day.today")
                } else if (dayMsValue === todayMs - dayMs) {
                    label = t("profileSettings.learning.day.yesterday")
                } else {
                    label = at.toLocaleDateString(locale, {
                        day: "numeric",
                        month: "long",
                        year: "numeric",
                    })
                }
                const key = String(dayMsValue)
                const last = groups[groups.length - 1]
                if (last && last.key === key) {
                    last.items.push(item)
                } else {
                    groups.push({ key, label, items: [item] })
                }
            }
            return groups
        },
        [
            filtered,
            locale,
            t,
        ],
    )

    return (
        <div>
            <AsyncContent
                isLoading={isLoading && items.length === 0}
                skeleton={(
                    <StackV gap={6} principle="block-boundary" explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups." items={[0, 1].map(() => () => (
                        <StackV
                            gap={4}
                            principle="sibling-stack"
                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                            items={[
                                () => <Skeleton.Typography type="body-xs" width="1/4" />,
                                () => <Skeleton.ListRow withTrailing />,
                                () => <Skeleton.ListRow withTrailing />,
                                () => <Skeleton.ListRow withTrailing />,
                            ]}
                        />
                    ))} />
                )}
                isEmpty={items.length === 0}
                emptyContent={{
                    title: t("profileSettings.learning.day.empty"),
                    description: t("profileSettings.learning.day.emptyHint"),
                }}
                error={items.length === 0 ? error : undefined}
                errorContent={{
                    title: t("profileSettings.learning.outline.error"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("profileSettings.learning.loadMore"),
                }}
            >
                {filtered.length === 0 ? (
                // loaded but the current search matches no event
                    <AsyncContentEmpty title={t("profileSettings.learning.day.noMatch")} />
                ) : (
                    <StackV
                        gap={6}
                        principle="block-boundary"
                        explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                        items={[
                            ...dayGroups.map((group) => () => (
                                <StackV
                                    gap={4}
                                    principle="sibling-stack"
                                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                    items={[
                                        () => (
                                            <Typography type="body-xs" color="muted" weight="medium">
                                                {group.label}
                                            </Typography>
                                        ),
                                        () => (
                                            <StackV
                                                gap={3}
                                                principle="sibling-stack"
                                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                items={group.items.map((item) => () => {
                                                    const Icon = EVENT_ICON[item.type]
                                                    const relative = getTimeAgoLabel(getTimeAgoMessage(item.at), t)
                                                    const subtitle = item.moduleTitle
                                                        ?? t(`profileSettings.learning.day.eventType.${item.type}`)
                                                    return (
                                                        <ListRow
                                                            leading={(
                                                                <IconTile
                                                                    size="sm"
                                                                    tone={EVENT_TONE[item.type]}
                                                                    icon={<Icon aria-hidden focusable="false" />}
                                                                />
                                                            )}
                                                            title={item.label}
                                                            subtitle={subtitle}
                                                            meta={(
                                                                <>
                                                                    {item.difficulty ? (
                                                                        <DifficultyChip difficulty={toDifficulty(item.difficulty)} />
                                                                    ) : null}
                                                                    <Typography type="body-xs" color="muted">
                                                                        <span title={formatDateTime(item.at, locale)}>{relative}</span>
                                                                    </Typography>
                                                                </>
                                                            )}
                                                        />
                                                    )
                                                })}
                                            />
                                        ),
                                    ]}
                                />
                            )),
                            ...(hasMore ? [() => (
                                <div className="flex justify-center">
                                    <Button
                                        variant="secondary"
                                        size="sm"
                                        isPending={isLoadingMore}
                                        onPress={() => setSize(size + 1)}
                                    >
                                        {t("profileSettings.learning.loadMore")}
                                    </Button>
                                </div>
                            )] : []),
                        ]}
                    />
                )}
            </AsyncContent>
        </div>
    )
}

"use client"

import React, {
    useState,
} from "react"
import {
    Input,
    Link,
    TextField,
    Typography,
} from "@heroui/react"
import {
    useTranslations,
} from "next-intl"
import {
    ArrowLeftIcon,
    BookOpenIcon,
    FlagIcon,
    ListBulletsIcon,
} from "@phosphor-icons/react"
import {
    CourseTrialChip,
} from "@/components/blocks/course/CourseTrialChip"
import {
    useSelectedCourse,
} from "@/hooks/useSelectedCourse"
import {
    CourseOutline,
} from "../CourseOutline"
import {
    CourseMilestoneOutline,
} from "../CourseMilestoneOutline"
import { useQueryMyCourseOutlineSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCourseOutlineSwr"
import { useQueryMyCoursesSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyCoursesSwr"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { fromGlobalId } from "@/modules/utils/globalId"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"

/** Detail view tabs: course content vs the personal-project capstone. */
type DetailTab = "contents" | "personalProject"

/** Segment colour per course progress dimension. */
const DIM_COLOR: Record<string, string> = {
    content: "var(--accent)",
    challenge: "var(--success)",
    milestone: "var(--warning)",
}

/**
 * Per-course detail. A sticky course header ({@link IconTile} + title +
 * completion % + {@link SegmentBar} + a meta line of lessons / challenges /
 * milestones), a client search over the active tab, and a two-tab toggle ΓÇö both
 * tabs render an accordion-card off the SAME `myCourseOutline` payload:
 *
 *   - "Contents" (default): the {@link CourseOutline} module ΓåÆ lesson ΓåÆ
 *     challenge tree with read flags.
 *   - "Personal Project": the {@link CourseMilestoneOutline}
 *     milestone ΓåÆ task tree with a roll-up completion status per milestone.
 *
 * Reads the selected course globalId from `?course=` (decoded to the raw id for
 * the shared outline query in each tab).
 */
export const CourseDetail = () => {
    const t = useTranslations()
    const { selectedCourse, setSelectedCourse } = useSelectedCourse()
    const [tab, setTab] = useState<DetailTab>("contents")
    const [search, setSearch] = useState("")

    // decode the selected course globalId (CourseEntity:<id>) ΓåÆ raw id for the outline query
    const rawCourseId = selectedCourse ? fromGlobalId(selectedCourse)?.id ?? null : null
    const outlineSwr = useQueryMyCourseOutlineSwr(rawCourseId)
    const outline = outlineSwr.data
    // the outline payload has no cover; reuse the (cached) course list to show the real
    // course logo in the header IconTile, like the hub list does ΓÇö falls back to the book icon.
    const coursesSwr = useQueryMyCoursesSwr()
    const selectedCourseItem = (coursesSwr.data ?? [])
        .find((course) => course.globalId === selectedCourse)
    const courseThumbnailUrl = selectedCourseItem?.thumbnailUrl
    const query = search.trim().toLowerCase()

    const progress = outline?.progress
    const headerDims = progress
        ? [
            { key: "content", completed: progress.lessonsRead, total: progress.lessonsTotal },
            { key: "challenge", completed: progress.challengesCompleted, total: progress.challengesTotal },
            { key: "milestone", completed: progress.tasksCompleted, total: progress.tasksTotal },
        ]
        : []
    const headerTotal = headerDims.reduce((acc, dim) => acc + dim.total, 0)

    return (
        <StackV
            gap={6}
            principle="block-boundary"
            explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major course-detail sections rather than nested section groups."
            items={[
                () => (
                    <Link onPress={() => { setSelectedCourse(null) }} className="text-sm text-muted">
                        <StackH
                            inline
                            gap={3}
                            principle="identity"
                            explain="Keeps avatar and identity text as one peer unit so the person label stays beside the face."
                            align="center"
                            items={[
                                () => <ArrowLeftIcon aria-hidden focusable="false" className="size-5" />,
                                () => <>{t("profileSettings.learning.history.title")}</>,
                            ]}
                        />
                    </Link>
                ),
                () => (
                    /* sticky course header ΓÇö title + progress + meta */
                    <Box principle="row-pad" className="sticky top-16 z-30 -mx-4 bg-background px-4 py-3"
                        explain="Row content inset ΓÇö not cell-pad, because this pads a horizontal content row rather than a dense table cell.">
                        <StackV gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <AsyncContent
                                        isLoading={outlineSwr.data === null || outlineSwr.data === undefined ? !outlineSwr.error : false}
                                        skeleton={(
                                            <StackH gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                align="center" items={[
                                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                    () => (
                                                        <StackV gap={3} principle="sibling-stack"
                                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                            classNames={["min-w-0", "flex-1"]} items={[
                                                                () => <Skeleton.Typography type="h4" width="1/2" />,
                                                                () => <Skeleton.ProgressBar />,
                                                            ]} />
                                                    ),
                                                ]} />
                                        )}
                                        isEmpty={!outline}
                                        emptyContent={{ title: t("profileSettings.learning.outline.empty") }}
                                        error={!outlineSwr.data ? outlineSwr.error : undefined}
                                        errorContent={{
                                            title: t("profileSettings.learning.outline.error"),
                                            onRetry: () => { void outlineSwr.mutate() },
                                            retryLabel: t("profileSettings.learning.loadMore"),
                                        }}
                                    >
                                        {outline && progress ? (
                                            <StackH gap={4} principle="content-row"
                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                align="center" items={[
