import { SegmentBar } from "@/components/composites/stats/SegmentBar"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { pathConfig } from "@/resources/path"
import { StackH, StackV } from "@/components/frames/Stack"

/** Props for {@link LearningHistoryPage}. */
export type LearningHistoryPageProps = Record<string, never>
/** Number of placeholder course cards shown while the hub loads. */
const SKELETON_COURSE_COUNT = 3

/** Hub-search appears only once the list has at least this many courses. */
const SEARCH_MIN_COURSES = 4

/** Segment colour per course progress dimension. */
const DIM_COLOR: Record<string, string> = {
    content: "var(--accent)",
    challenge: "var(--success)",
    milestone: "var(--warning)",
}

/**
 * Learning history (brainstorm direction A / H1). The HUB lists every joined
 * course as a hinh-2 card ΓÇö an {@link IconTile}, the title + overall completion %,
 * and a {@link SegmentBar} folding the three dimensions (content / challenge /
 * milestone) into one honest bar ΓÇö each a press target opening that course's
 * detail (written into `?course=`). A client search filters the cards by title,
 * shown only when there are several courses. When a course is selected, the
 * {@link CourseDetail} view (day timeline + chapter outline) replaces the grid.
 *
 * @param props - optional root className (placement only).
 */
export const LearningHistoryPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const { selectedCourse, setSelectedCourse } = useSelectedCourse()
    const [search, setSearch] = useState("")
    const coursesSwr = useQueryMyCoursesSwr()
    const courses = useMemo(() => coursesSwr.data ?? [], [coursesSwr.data])

    // search filters the loaded courses by title, client-side
    const query = search.trim().toLowerCase()
    const filtered = useMemo(
        () => (query
            ? courses.filter((course) => course.label.toLowerCase().includes(query))
            : courses),
        [courses, query],
    )

    // a selected course ΓåÆ show its detail (day timeline + chapter outline)
    if (selectedCourse) {
        return <CourseDetail />
    }

    return (
        <div className={"flex flex-col gap-10"}>
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("profileSettings.learning.history.title")} />}
                title={t("profileSettings.learning.history.title")}
                description={t("profileSettings.learning.history.subtitle")}
            />
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                // search ΓÇö only worth showing once there are several courses
                    () => (courses.length >= SEARCH_MIN_COURSES ? (
                        <TextField variant="secondary">
                            <Input
                                aria-label={t("profileSettings.learning.history.searchCourses")}
                                placeholder={t("profileSettings.learning.history.searchCourses")}
                                value={search}
                                onChange={(event) => setSearch(event.target.value)}
                            />
                        </TextField>
                    ) : null),

                    () => {
                        const skeletonItems: Array<SurfaceCardListItem> = Array.from(
                            { length: SKELETON_COURSE_COUNT },
                            (_unused, row) => ({
                                key: `skeleton-${row}`,
                                content: () => (
                                    <StackH gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        align="center" items={[
                                            () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                            () => (
                                                <StackV gap={3} principle="sibling-stack"
                                                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                    classNames={["min-w-0", "flex-1"]} items={[
                                                        () => (
                                                            <StackH gap={3} principle="value-row"
                                                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                                justify="between" align="center" items={[
                                                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                                                    () => <Skeleton className="h-3 w-8 rounded" />,
                                                                ]} />
                                                        ),
                                                        () => <Skeleton.ProgressBar />,
                                                    ]} />
                                            ),
                                        ]} />
                                ),
                            }),
                        )

                        const courseItems: Array<SurfaceCardListItem> = filtered.map((course) => {
                            const dims = [
                                { key: "content", completed: course.contentCompleted, total: course.contentTotal },
                                { key: "challenge", completed: course.challengeCompleted, total: course.challengeTotal },
                                { key: "milestone", completed: course.completed, total: course.total },
                            ]
                            const totalTasks = dims.reduce((acc, dim) => acc + dim.total, 0)
                            return {
                                key: course.globalId,
                                onPress: () => { setSelectedCourse(course.globalId) },
                                hover: "underline" as const,
                                content: () => (
                                    <StackH gap={4} principle="content-row"
                                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                        align="center" items={[
                                            () => <IconTile size="sm" src={course.thumbnailUrl} icon={<BookOpenIcon aria-hidden focusable="false" />} />,
                                            () => (
                                                <StackV gap={3} principle="sibling-stack"
                                                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                    classNames={["min-w-0", "flex-1"]} items={[
                                                        () => (
                                                            <StackH gap={3} principle="value-row"
                                                                explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
                                                                justify="between" align="center" items={[
                                                                    () => (
                                                                        <Typography type="body-sm" weight="semibold" truncate className="min-w-0 flex-1 underline-offset-4 decoration-[var(--separator-tertiary)] group-hover:underline">
                                                                            {course.label}
                                                                        </Typography>
                                                                    ),
                                                                    () => <CourseTrialChip isEnrolled={course.isEnrolled} />,
                                                                    () => (
                                                                        <Typography type="body-xs" color="muted">
                                                                            {`${course.completionPercent}%`}
                                                                        </Typography>
                                                                    ),
                                                                ]} />
                                                        ),
                                                        () => (
                                                            <SegmentBar
                                                                max={totalTasks || 1}
                                                                ariaLabel={`${course.label} ┬╖ ${course.completionPercent}%`}
                                                                segments={dims.map((dim) => ({
                                                                    key: dim.key,
                                                                    label: t(`dashboard.courseProgress.${dim.key}`),
                                                                    value: dim.completed,
                                                                    color: DIM_COLOR[dim.key],
                                                                }))}
                                                            />
                                                        ),
                                                    ]} />
                                            ),
                                        ]} />
                                ),
                            }
                        })

                        return (
                            <AsyncContent
                                isLoading={!coursesSwr.data && !coursesSwr.error}
                                skeleton={<SurfaceCardList items={skeletonItems} />}
                                isEmpty={courses.length === 0}
                                emptyContent={{
                                    title: t("profileSettings.learning.history.coursesEmpty"),
                                    description: t("profileSettings.learning.history.coursesEmptyHint"),
                                    onRetry: () => { router.push(pathConfig().locale(locale).course().build()) },
                                    retryLabel: t("profileSettings.learning.history.explore"),
                                }}
                                error={!coursesSwr.data ? coursesSwr.error : undefined}
                                errorContent={{
                                    title: t("profileSettings.learning.outline.error"),
                                    onRetry: () => { void coursesSwr.mutate() },
                                    retryLabel: t("profileSettings.learning.loadMore"),
                                }}
                            >
                                {filtered.length === 0 ? (
                                    <AsyncContentEmpty title={t("profileSettings.learning.history.noMatch")} />
                                ) : (
                                    <SurfaceCardList items={courseItems} />
                                )}
                            </AsyncContent>
                        )
                    },
                ]} />
        </div>
    )
}

"use client"

import React, { useEffect } from "react"
import { Button, Spinner, Typography } from "@heroui/react"
import { useRouter, useSearchParams } from "next/navigation"
import { useLocale, useTranslations } from "next-intl"
import { pathConfig } from "@/resources/path"

import { OauthAction } from "@/modules/types/enums/oauth-action"
import { OAUTH_ACTION_MESSAGE_KEY_MAP } from "@/modules/utils/oauth-action-message"
import { Spacer } from "@/components/blocks/layout/Spacer"
import { SessionStorage } from "@/modules/storage/session/storage"
import { SessionStorageId } from "@/modules/storage/session/enums/id"
import { type SessionStoragePostLoginRedirect } from "@/modules/storage/session/types/post-login-redirect"
import { StackV } from "@/components/frames/Stack"

export * from "@/modules/types/enums/oauth-action"

/** Props for {@link OauthRedirectPage}. */
export interface OauthRedirectPageProps {
    /**
     * The OAuth lifecycle step this redirect page represents ΓÇö selects the i18n
     * message shown under the spinner. The redirect destination (locale home)
     * and delay are identical for every step.
     */
    action: OauthAction
}

/**
 * OAuth redirect landing ΓÇö shown after a Keycloak provider hand-off
 * (login / logout / generic authenticate). Waits ~1s, then sends the user to
 * the locale home. Presentational shell + the redirect effect.
 *
 * `"use client"`: relies on `useRouter`, `useEffect` and `useLocale`.
 */
export const OauthRedirectPage = ({ action}: OauthRedirectPageProps) => {
    const router = useRouter()
    const locale = useLocale()
    const t = useTranslations()
    const searchParams = useSearchParams()

    // Keycloak (and the OAuth2 spec) hands back a failed/cancelled round-trip on the
    // redirect_uri as `?error=...` (e.g. `access_denied`), never establishing a session.
    // Detect it BEFORE redirecting so we don't drop the user home wearing success chrome.
    const hasOauthError = Boolean(searchParams.get("error"))

    // Hold the user briefly so the Keycloak session settles, then continue on: a sign-in
    // started from the `/login` guard stashed where the visitor was headed (query params
    // don't survive the IdP round-trip); anything else (logout, generic authenticate) goes home.
    // setTimeout (not `sleep().then()`) so the pending redirect is cancelled via cleanup if
    // this page unmounts within the delay ΓÇö `sleep()`'s promise can't be cancelled.
    useEffect(() => {
        // a failed/cancelled hand-off never authenticated the user ΓÇö render the failure
        // state instead of forwarding them on as if signed in.
        if (hasOauthError) {
            return
        }
        const handle = setTimeout(() => {
            let target: string | undefined
            if (action === OauthAction.Login) {
                const stashed = SessionStorage.getItem<SessionStoragePostLoginRedirect>(
                    SessionStorageId.PostLoginRedirect,
                )
                target = stashed?.target
                SessionStorage.removeItem(SessionStorageId.PostLoginRedirect)
            }
            router.push(target ?? pathConfig().locale(locale).build())
        }, 1000)

        return () => clearTimeout(handle)
    }, [action, locale, router, hasOauthError])

    if (hasOauthError) {
        const errorItems = [
            () => (
                <Typography type="h5" weight="semibold" align="center">
                    {t("auth.oauth.failedTitle")}
                </Typography>
            ),
            () => (
                <Typography type="body-sm" color="muted" align="center">
                    {t("auth.oauth.failedDescription")}
                </Typography>
            ),
            () => <Spacer y={3} />,
            () => (
                <Button
                    variant="primary"
                    onPress={() => router.replace(pathConfig().locale(locale).login().build())}
                >
                    {t("auth.oauth.retry")}
                </Button>
            ),
        ]
        return (
            <div className={"flex min-h-[60vh] flex-col items-center justify-center"}>
                <div className="max-w-sm text-center">
                    <StackV
                        gap={3}
                        align="center"
                        principle="sibling-stack"
                        explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                        items={errorItems}
                    />
                </div>
            </div>
        )
    }

    const loadingItems = [
        () => (
            <Spinner
                color="accent"
                size="lg"
            />
        ),
        () => <Spacer y={3} />,
        () => (
            <div className="text-sm">
                {t(OAUTH_ACTION_MESSAGE_KEY_MAP[action])}
            </div>
        ),
    ]

    return (
        <div className={"flex min-h-[60vh] flex-col items-center justify-center"}>
            <StackV gap={3} align="center" principle="sibling-stack"
                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                items={loadingItems}  />
        </div>
    )
}

"use client"

import React from "react"
import { Chip, Skeleton } from "@heroui/react"
import { useLocale, useTranslations } from "next-intl"
import {
    ReceiptIcon,
    TicketIcon,
} from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import {
    SurfaceCardList,
    type SurfaceCardListItem,
} from "@/components/composites/cards/SurfaceCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyVouchersSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyVouchersSwr"
import { pathConfig } from "@/resources/path"
import type { QueryMyVoucherData } from "@/modules/api/graphql/queries/types/my-vouchers"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** Chip color per voucher lifecycle status. */
const STATUS_COLOR: Record<string, "accent" | "warning" | "default" | "danger"> = {
    unused: "accent",
    reserved: "warning",
    used: "default",
    expired: "danger",
}

/** Format a voucher's discount as a short label, e.g. "-10%" / "-50,000 VND". */
const discountLabel = (voucher: QueryMyVoucherData): string => (
    voucher.discountType === "percent"
        ? `-${voucher.value}%`
        // Dong suffix via code point ΓÇö keeps the source free of Vietnamese letters.
        : `-${voucher.value.toLocaleString("vi-VN")}${String.fromCharCode(0x0111)}`
)

/** Props for {@link MyVouchers}. */
export type MyVouchersProps = Record<string, never>
/**
 * The Coin shop's "My wallet" tab: the viewer's minted vouchers (code, scope,
 * status, expiry) plus the redemption history. Self-fetches both ΓÇö the
 * `myRewardWallet` key is shared with the header/catalog, so a redeem
 * elsewhere refreshes this list without a manual prop.
 *
 * @param props - optional className for the root element.
 */
export const MyVouchers = () => {
    const t = useTranslations()
    const locale = useLocale()
    const vouchersSwr = useQueryMyVouchersSwr()
    const walletSwr = useQueryMyRewardWalletSwr()

    const vouchersLoading = !vouchersSwr.data
    const walletLoading = !walletSwr.data

    const voucherSkeletonItems: Array<SurfaceCardListItem> = Array.from({ length: 2 }, (_row, index) => ({
        key: `voucher-skeleton-${index}`,
        title: "ΓÇª",
        subtitle: "ΓÇª",
        leading: () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
    }))

    const voucherItems: Array<SurfaceCardListItem> = (vouchersSwr.data ?? []).map((voucher) => ({
        key: voucher.id,
        // `subtitle` is plain text now (never a built element), so the
        // course reference can no longer carry its own inline link ΓÇö the
        // whole row becomes the link instead (`href` below), which is a
        // bigger, easier-to-hit target than the old inline text anyway.
        leading: () => (
            <IconTile
                size="sm"
                tone="accent"
                icon={<TicketIcon aria-hidden focusable="false" />}
            />
        ),
        title: voucher.code,
        subtitle: voucher.courseId
            ? t("rewards.myVouchers.scopeCourse", {
                course: voucher.courseTitle ?? "",
            }).replace(/<\/?link>/g, "")
            : t("rewards.myVouchers.scopeAny"),
        href: voucher.courseDisplayId
            ? pathConfig().locale(locale).course(voucher.courseDisplayId).build()
            : undefined,
        meta: () => (
            <span className="text-sm font-medium text-foreground">
                {discountLabel(voucher)}
            </span>
        ),
        trailing: () => (
            <Chip color={STATUS_COLOR[voucher.status] ?? "default"} variant="soft" size="sm">
                <Chip.Label>
                    {t(`rewards.myVouchers.status.${voucher.status}`)}
                </Chip.Label>
            </Chip>
        ),
    }))

    const redemptionSkeletonItems: Array<SurfaceCardListItem> = Array.from({ length: 3 }, (_row, index) => ({
        key: `redemption-skeleton-${index}`,
        title: "ΓÇª",
        metaText: "ΓÇª",
    }))

    const redemptionItems: Array<SurfaceCardListItem> = (walletSwr.data?.redemptions ?? []).map((redemption, index) => ({
        key: `${redemption.rewardKey}-${redemption.createdAt}-${index}`,
        title: redemption.title,
        subtitle: new Date(redemption.createdAt).toLocaleDateString(locale),
        meta: () => (
            <span className="text-xs text-muted">
                {t(`rewards.status.${redemption.status}`)}
            </span>
        ),
        trailing: () => (
            <span className="text-sm font-medium text-foreground">
                {t("rewards.cost", { count: redemption.cost })}
            </span>
        ),
    }))

    return (
        <Box identity={{ tier: "page", component: "MyVouchers" }}>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <SurfaceCardList
                            label={t("rewards.myVouchers.title")}
                            items={vouchersLoading ? voucherSkeletonItems : voucherItems}
                            isSkeleton={vouchersLoading}
                            emptyState={() => (
                                <AsyncContentEmpty
                                    icon={TicketIcon}
                                    title={t("rewards.myVouchers.empty")}
                                    description={t("rewards.myVouchers.emptyHint")}
                                />
                            )}
                            error={!vouchersSwr.data ? vouchersSwr.error : undefined}
                            errorState={() => (
                                <AsyncContentError
                                    title={t("rewards.myVouchers.error")}
                                    onRetry={() => void vouchersSwr.mutate()}
                                />
                            )}
                        />
                    ),

                    () => (
                        <SurfaceCardList
                            label={t("rewards.redeemedTitle")}
                            items={walletLoading ? redemptionSkeletonItems : redemptionItems}
                            isSkeleton={walletLoading}
                            emptyState={() => (
                                <AsyncContentEmpty
                                    icon={ReceiptIcon}
                                    title={t("rewards.noRedemptions")}
                                />
                            )}
                            error={!walletSwr.data ? walletSwr.error : undefined}
                            errorState={() => (
                                <AsyncContentError
                                    title={t("rewards.myVouchers.error")}
                                    onRetry={() => void walletSwr.mutate()}
                                />
                            )}
                        />
                    ),
                ]} />
        </Box>
    )
}

"use client"

import React, {
    useCallback,
    useState,
} from "react"
import type { ReactNode } from "react"
import {
    Button,
    Card,
    Chip,
    Input,
    Label,
    Skeleton,
    TextField,
    Typography,
} from "@heroui/react"
import { toast } from "@/modules/toast/toast"
import { useTranslations } from "next-intl"
import {
    CheckCircleIcon,
    CopyIcon,
    GiftIcon,
    LightningIcon,
    SnowflakeIcon,
    TShirtIcon,
    TicketIcon,
} from "@phosphor-icons/react"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { Callout } from "@/components/composites/feedback/Callout"
import { LabeledCard } from "@/components/blocks/cards/LabeledCard"
import { IconTile } from "@/components/blocks/identity/IconTile"
import { ModalShell } from "@/components/composites/layout/ModalShell"
import { useMutateRedeemRewardSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRedeemRewardSwr"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyVouchersSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyVouchersSwr"
import { useQueryRewardsSwr } from "@/hooks/swr/api/graphql/queries/useQueryRewardsSwr"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import type { QueryRewardData } from "@/modules/api/graphql/queries/types/rewards"
import type { RedeemRewardAiCreditGrant } from "@/modules/api/graphql/mutations/types/redeem-reward"
import { Box } from "@/components/frames/Box"
import { Grid } from "@/components/frames/Grid"
import { StackH, StackV } from "@/components/frames/Stack"

/** Icon per catalog item, keyed by its stable reward key (falls back to a generic gift). */
const REWARD_ICON: Record<string, ReactNode> = {
    streakFreeze: <SnowflakeIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    aiCreditBoost: <LightningIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    voucher10: <TicketIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
    tshirt: <TShirtIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />,
}

/**
 * Coin-shop catalog grouped into user-facing SECTIONS by reward `kind` (instructor's
 * call, 2026-07-17, "split into more categories"). `aiCredit` + `digital` read as one
 * "speed up learning" bucket; `voucher` and `physical` each stand alone. Order = display
 * order. A reward whose `kind` matches no section is not shown in the grouped view ΓÇö
 * every current kind is covered here; adding a new kind means adding a section.
 */
const REWARD_SECTIONS: ReadonlyArray<{ key: string, icon: ReactNode, kinds: ReadonlyArray<string> }> = [
    { key: "learn", icon: <LightningIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["aiCredit", "digital"] },
    { key: "voucher", icon: <TicketIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["voucher"] },
    { key: "physical", icon: <GiftIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />, kinds: ["physical"] },
]

/** One redeem effect's takeaway shown right after redeeming (voucher code / AI-credit bump). */
type JustRedeemed =
    | { kind: "voucher", code: string }
    | { kind: "aiCredit", grant: RedeemRewardAiCreditGrant }

/** Shipping form fields (physical rewards only). */
interface ShippingForm {
    recipientName: string
    phone: string
    address: string
}

const EMPTY_SHIPPING: ShippingForm = {
    recipientName: "",
    phone: "",
    address: "",
}

/** Props for {@link RewardCatalog}. */
export type RewardCatalogProps = Record<string, never>
/**
 * The Coin shop's "Store" tab: the redeemable catalog grid. Self-fetches the
 * catalog + the viewer's balance (the wallet SWR key is shared with the header
 * and the "My Wallet" tab, so a redeem here refreshes both instantly). Physical
 * rewards expand an inline shipping form before redeeming; a `voucher`/`aiCredit`
 * redemption surfaces its takeaway (code to copy / bonus credit granted) in a
 * dismissible callout above the grid.
 *
 * @param props - optional className for the root element.
 */
export const RewardCatalog = () => {
    const t = useTranslations()
    const rewardsSwr = useQueryRewardsSwr()
    const walletSwr = useQueryMyRewardWalletSwr()
    const vouchersSwr = useQueryMyVouchersSwr()
    const { trigger: triggerRedeem } = useMutateRedeemRewardSwr()
    const runGraphQL = useGraphQLWithToast()

    /** The reward key currently being redeemed (single in-flight redeem). */
    const [redeeming, setRedeeming] = useState<string | null>(null)
    /** The physical reward whose shipping form is open (null = none). */
    const [shippingFor, setShippingFor] = useState<string | null>(null)
    const [ship, setShip] = useState<ShippingForm>(EMPTY_SHIPPING)
    /** The takeaway of the most recent voucher/aiCredit redemption, if any. */
    const [justRedeemed, setJustRedeemed] = useState<JustRedeemed | null>(null)
    /** A non-physical reward awaiting spend confirmation (Coin is real, redeem is irreversible). */
    const [confirming, setConfirming] = useState<QueryRewardData | null>(null)

    const balance = walletSwr.data?.balance ?? 0

    const onRedeem = useCallback(
        async (reward: QueryRewardData, shipping?: ShippingForm) => {
            setRedeeming(reward.key)
            try {
                let redeemed: { voucherCode?: string | null, aiCreditGranted?: RedeemRewardAiCreditGrant | null } | undefined
                const ok = await runGraphQL(async () => {
                    const result = await triggerRedeem({
                        rewardKey: reward.key,
                        ...shipping,
                    })
                    const wrapped = result.data!.redeemReward
                    redeemed = wrapped.data
                    return wrapped
                })
                if (ok) {
                    await walletSwr.mutate()
                    if (reward.kind === "voucher" && redeemed?.voucherCode) {
                        setJustRedeemed({ kind: "voucher", code: redeemed.voucherCode })
                        await vouchersSwr.mutate()
                    } else if (reward.kind === "aiCredit" && redeemed?.aiCreditGranted) {
                        setJustRedeemed({ kind: "aiCredit", grant: redeemed.aiCreditGranted })
                    }
                    // close + reset the shipping form on success
                    setShippingFor(null)
                    setShip(EMPTY_SHIPPING)
                }
            } finally {
                setRedeeming(null)
            }
        },
        [
            triggerRedeem,
            walletSwr,
            vouchersSwr,
            runGraphQL,
        ],
    )

    const onCopyCode = useCallback(
        async (code: string) => {
            try {
                await navigator.clipboard.writeText(code)
                toast.success(t("rewards.myVouchers.copied"))
            } catch {
                // clipboard blocked (permissions/http) ΓåÆ no-op, code is still selectable text
            }
        },
        [t],
    )

    return (
        <Box>
            <StackV gap={4} principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => (justRedeemed ? (
                        <Callout
                            status="accent"
                            icon={CheckCircleIcon}
                            title={
                                justRedeemed.kind === "voucher"
                                    ? t("rewards.justRedeemed.voucherTitle")
                                    : t("rewards.justRedeemed.aiCreditTitle")
                            }
                            description={
                                justRedeemed.kind === "voucher"
                                    ? undefined
                                    : t("rewards.justRedeemed.aiCreditDescription", {
                                        amount5h: justRedeemed.grant.amount5h,
                                        amountWeek: justRedeemed.grant.amountWeek,
                                    })
                            }
                            body={justRedeemed.kind === "voucher" ? () => (
                                <StackH gap={3} principle="flex-action"
                                    explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                    align="center" items={[
                                        () => <span className="font-mono font-medium text-foreground">{justRedeemed.code}</span>,
                                        () => (
                                            <Button
                                                variant="tertiary"
                                                size="sm"
                                                onPress={() => void onCopyCode(justRedeemed.code)}
                                            >
                                                <CopyIcon aria-hidden focusable="false" className="size-4" />
                                                {t("rewards.myVouchers.copy")}
                                            </Button>
                                        ),
                                    ]} />
                            ) : undefined}
                            onClose={() => setJustRedeemed(null)}
                            closeAriaLabel={t("rewards.justRedeemed.dismiss")}
                        />
                    ) : null),

                    () => (
                        <AsyncContent
                            isLoading={!rewardsSwr.data}
                            skeleton={(
                                <Grid
                                    columns={{ base: 1, sm: 2 }}
                                    principle="content-row"
                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                    items={Array.from({ length: 4 }).map((_, index) => ({
                                        key: String(index),
                                        content: () => (
                                            <Box principle="card-padding" className="rounded-3xl bg-surface p-4 shadow-surface"
                                                explain="Card body inset ΓÇö not page-pad, because this is the surface padding of a card rather than the page chrome.">
                                                <StackV gap={4} principle="content-row"
                                                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                    items={[
                                                        () => (
                                                            <StackH gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                align="center" items={[
                                                                    () => <Skeleton className="size-12 shrink-0 rounded-xl" />,
                                                                    () => <Skeleton className="h-4 w-1/2 rounded-lg" />,
                                                                ]} />
                                                        ),
                                                        () => <Skeleton className="h-4 w-full rounded-lg" />,
                                                        () => <Skeleton className="h-9 w-24 self-end rounded-lg" />,
                                                    ]} />
                                            </Box>
                                        ),
                                    }))}
                                />
                            )}
                            isEmpty={(rewardsSwr.data ?? []).length === 0}
                            emptyContent={{
                                icon: <GiftIcon aria-hidden focusable="false" className="size-8 text-muted" />,
                                title: t("rewards.catalogEmptyTitle"),
                                description: t("rewards.catalogEmptyDescription"),
                            }}
                            error={rewardsSwr.error}
                            errorContent={{
                                title: t("rewards.catalogError"),
                                onRetry: () => void rewardsSwr.mutate(),
                            }}
                        >
                            <StackV gap={6} principle="block-boundary" explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups." items={REWARD_SECTIONS.map((section) => () => {
                                const sectionItems = (rewardsSwr.data ?? []).filter((reward) => section.kinds.includes(reward.kind))
                                if (sectionItems.length === 0) {
                                    return null
                                }
                                return (
                                    <LabeledCard
                                        key={section.key}
                                        // `label` is plain text now (never a built element) ΓÇö `LabeledCard`
                                        // has no leading-icon slot the way `SectionCard` does, so the
                                        // per-section icon has nowhere left to attach (flagged for a
                                        // follow-up: a real icon slot on `LabeledCard`, or switch this
                                        // section header to `SectionCard`).
                                        label={t(`rewards.section.${section.key}`)}
                                    >
                                        <Grid
                                            columns={{ base: 1, sm: 2 }}
                                            principle="content-row"
                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                            items={sectionItems.map((reward) => ({
                                                key: reward.key,
                                                content: () => {
                                                    const affordable = balance >= reward.cost
                                                    const isPhysical = reward.kind === "physical"
                                                    const formOpen = shippingFor === reward.key
                                                    const shipReady = Boolean(
                                                        ship.recipientName.trim()
                                && ship.phone.trim()
                                && ship.address.trim(),
                                                    )
                                                    return (
                                                        <Card>
                                                            <StackV gap={4} principle="content-row"
                                                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                items={[
                                                                    () => (
                                                                        <StackH gap={4} principle="content-row"
                                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                            align="start" items={[
                                                                                () => (
                                                                                    <IconTile
                                                                                        size="sm"
                                                                                        tone="accent"
                                                                                        icon={REWARD_ICON[reward.key] ?? (
                                                                                            <GiftIcon aria-hidden focusable="false" className="size-5 text-accent-soft-foreground" />
                                                                                        )}
                                                                                    />
                                                                                ),
                                                                                () => (
                                                                                    <StackV gap={1} principle="name-handle"
                                                                                        explain="Display name with handle ΓÇö not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                                                                        classNames={["min-w-0", "flex-1"]} items={[
                                                                                            () => (
                                                                                                <span className="truncate text-sm font-semibold text-foreground">
                                                                                                    {reward.title}
                                                                                                </span>
                                                                                            ),
                                                                                            () => (
                                                                                                <span className="text-xs text-muted">
                                                                                                    {reward.description}
                                                                                                </span>
                                                                                            ),
                                                                                        ]} />
                                                                                ),
                                                                            ]} />
                                                                    ),
                                                                    () => (
                                                                        <StackH gap={4} principle="content-row" justify="between" align="center"
                                                                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                                                            items={[
                                                                                () => (
                                                                                    <Chip color="accent" variant="soft" size="sm">
                                                                                        <Chip.Label>
                                                                                            {t("rewards.cost", { count: reward.cost })}
                                                                                        </Chip.Label>
                                                                                    </Chip>
                                                                                ),
                                                                                () => (!formOpen ? (
                                                                                    <Button
                                                                                        variant="primary"
                                                                                        size="sm"
                                                                                        isDisabled={!affordable || redeeming !== null}
                                                                                        isPending={redeeming === reward.key}
                                                                                        onPress={() => {
                                                                                            if (isPhysical) {
                                                                                                setShippingFor(reward.key)
                                                                                            } else {
                                                                                                // Coin is real + redeem is irreversible ΓÇö confirm
                                                                                                // before spending (mirrors the shipping form's own
                                                                                                // "Confirm redeem" step for physical rewards).
                                                                                                setConfirming(reward)
                                                                                            }
                                                                                        }}
                                                                                    >
                                                                                        {affordable
                                                                                            ? t("rewards.redeem")
                                                                                            : t("rewards.cannotAfford")}
                                                                                    </Button>
                                                                                ) : null),
                                                                            ]} />
                                                                    ),
                                                                    () => (formOpen ? (
                                                                        <StackV gap={3} principle="sibling-stack"
                                                                            explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                                                            items={[
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-name-${reward.key}`}>
                                                                                            {t("rewards.shipName")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-name-${reward.key}`}
                                                                                            value={ship.recipientName}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                recipientName: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-phone-${reward.key}`}>
                                                                                            {t("rewards.shipPhone")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-phone-${reward.key}`}
                                                                                            type="tel"
                                                                                            value={ship.phone}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                phone: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <TextField variant="secondary">
                                                                                        <Label htmlFor={`reward-ship-address-${reward.key}`}>
                                                                                            {t("rewards.shipAddress")}
                                                                                        </Label>
                                                                                        <Input
                                                                                            id={`reward-ship-address-${reward.key}`}
                                                                                            value={ship.address}
                                                                                            onChange={(event) => setShip((prev) => ({
                                                                                                ...prev,
                                                                                                address: event.target.value,
                                                                                            }))}
                                                                                        />
                                                                                    </TextField>
                                                                                ),
                                                                                () => (
                                                                                    <StackH gap={3} principle="flex-action"
                                                                                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                                                                                        align="center" items={[
                                                                                            () => (
                                                                                                <Button
                                                                                                    variant="primary"
                                                                                                    size="sm"
                                                                                                    isDisabled={!shipReady || redeeming !== null}
                                                                                                    isPending={redeeming === reward.key}
                                                                                                    onPress={() => void onRedeem(reward, ship)}
                                                                                                >
                                                                                                    {t("rewards.confirmRedeem")}
                                                                                                </Button>
                                                                                            ),
                                                                                            () => (
                                                                                                <Button
                                                                                                    variant="tertiary"
                                                                                                    size="sm"
                                                                                                    onPress={() => setShippingFor(null)}
                                                                                                >
                                                                                                    {t("rewards.cancel")}
                                                                                                </Button>
                                                                                            ),
                                                                                        ]} />
                                                                                ),
                                                                            ]} />
                                                                    ) : null),
                                                                ]} />
                                                        </Card>
                                                    )
                                                },
                                            }))}
                                        />
                                    </LabeledCard>
                                )
                            })} />
                        </AsyncContent>
                    ),

                    // spend confirmation for non-physical rewards ΓÇö Coin is real + redeem is
                    // irreversible, so a single accidental tap must never fire it (mirrors the
                    // shipping form's own "Confirm redeem" step for physical rewards).
                    () => (
                        <ModalShell
                            isOpen={confirming !== null}
                            onOpenChange={(open) => {
                                if (!open) {
                                    setConfirming(null)
                                }
                            }}
                            title={t("rewards.confirmRedeem")}
                            size="sm"
                            body={() => (
                                <Typography type="body-sm" color="muted">
                                    {confirming
                                        ? t("rewards.confirmRedeemBody", { cost: confirming.cost, title: confirming.title })
                                        : null}
                                </Typography>
                            )}
                            footer={() => (
                                <>
                                    <Button variant="tertiary" onPress={() => setConfirming(null)}>
                                        {t("rewards.cancel")}
                                    </Button>
                                    <Button
                                        variant="primary"
                                        isPending={redeeming !== null}
                                        onPress={() => {
                                            const reward = confirming
                                            setConfirming(null)
                                            if (reward) {
                                                void onRedeem(reward)
                                            }
                                        }}
                                    >
                                        {t("rewards.confirmRedeem")}
                                    </Button>
                                </>
                            )}
                        />
                    ),
                ]} />
        </Box>
    )
}

"use client"

import React, { useState } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { CoinsIcon } from "@phosphor-icons/react"
import { HighlightChip } from "@/components/composites/chips/HighlightChip"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { ResponsiveBreadcrumb } from "@/components/blocks/navigation/ResponsiveBreadcrumb"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { useQueryMyRewardWalletSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyRewardWalletSwr"
import { useQueryMyVouchersSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyVouchersSwr"
import { pathConfig } from "@/resources/path"
import { MyVouchers } from "./MyVouchers"
import { RewardCatalog } from "./RewardCatalog"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"

/** The Coin shop's two tabs: buying new rewards vs owning/using them. */
enum RewardsTab {
    Shop = "shop",
    Wallet = "wallet",
}

/** Props for {@link RewardsPage}. */
export type RewardsPageProps = Record<string, never>
/**
 * The Coin shop: the viewer's spendable Coin balance in the header, a
 * "Store" tab (redeemable catalog) and a "My wallet" tab (minted vouchers +
 * redemption history). Tabs are local state ΓÇö this page is not deep-linked
 * into from elsewhere, so URL state isn't needed. See `fe/features/rewards.md`
 * (canon) for the shell/CTA/state rationale.
 *
 * @param props - optional className for the root element.
 */
export const RewardsPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const walletSwr = useQueryMyRewardWalletSwr()
    const vouchersSwr = useQueryMyVouchersSwr()
    const [tab, setTab] = useState<RewardsTab>(RewardsTab.Shop)

    const balance = walletSwr.data?.balance ?? 0
    const unusedVoucherCount = (vouchersSwr.data ?? []).filter(
        (voucher) => voucher.status === "unused",
    ).length

    return (
        <div className={""}>
            <Box principle="center-measure" className="mx-auto w-full max-w-3xl p-6"
                explain="Caps reading width so long copy does not stretch edge-to-edge across the viewport.">
                <StackV principle="layout-split"
                    explain="Major layout split ΓÇö not block-boundary, because this separates primary page regions rather than adjacent blocks."
                    items={[
                        () => (
                            <PageHeader
                                breadcrumb={(
                                    <ResponsiveBreadcrumb
                                        items={[
                                            {
                                                key: "home",
                                                label: t("nav.home"),
                                                onPress: () => router.push(pathConfig().locale(locale).build()),
                                            },
                                            {
                                                key: "rewards",
                                                label: t("rewards.title"),
                                            },
                                        ]}
                                    />
                                )}
                                title={t("rewards.title")}
                                description={t("rewards.description")}
                                meta={(
                                    <HighlightChip
                                        tone="accent"
                                        icon={CoinsIcon}
                                        value={balance}
                                        label={t("rewards.balanceLabel")}
                                    />
                                )}
                            />
                        ),
                        () => (
                            <StackV principle="block-boundary"
                                explain="Block-to-block spacing ΓÇö not group-boundary, because this separates major blocks rather than nested section groups."
                                items={[
                                    () => (
                                        <TabsCard
                                            leftTabs={{
                                                items: [
                                                    {
                                                        key: RewardsTab.Shop,
                                                        label: t("rewards.tabs.shop"),
                                                    },
                                                    {
                                                        key: RewardsTab.Wallet,
                                                        label: unusedVoucherCount > 0
                                                            ? t("rewards.tabs.walletWithCount", { count: unusedVoucherCount })
                                                            : t("rewards.tabs.wallet"),
                                                    },
                                                ],
                                                selectedKey: tab,
                                                ariaLabel: t("rewards.tabsAria"),
                                                onSelectionChange: (key) => setTab(key as RewardsTab),
                                            }}
                                        />
                                    ),
                                    () => (tab === RewardsTab.Shop ? <RewardCatalog /> : <MyVouchers />),
                                ]} />
                        ),
                    ]} />
            </Box>
        </div>
    )
}

"use client"

import {
    SignOutIcon,
    DesktopIcon,
    DeviceMobileIcon,
} from "@phosphor-icons/react"
import React, {
    useCallback,
    useState,
} from "react"
import {
    Button,
    Chip,
    Spinner,
    Typography,
} from "@heroui/react"
import {
    SettingsBreadcrumb,
} from "@/components/blocks/settings/SettingsBreadcrumb"
import {
    useLocale,
    useTranslations,
} from "next-intl"
import { AsyncContent } from "@/components/blocks/async/AsyncContent"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import { SurfaceCardList, type SurfaceCardListItem } from "@/components/composites/cards/SurfaceCard"
import { Box } from "@/components/frames/Box"
import { Cluster } from "@/components/frames/Cluster"
import { StackH, StackV } from "@/components/frames/Stack"
import { useQueryMySessionsSwr } from "@/hooks/swr/api/graphql/queries/useQueryMySessionsSwr"
import { useMutateRevokeSessionSwr } from "@/hooks/swr/api/graphql/mutations/useMutateRevokeSessionSwr"
import type { LoginSession } from "@/modules/api/graphql/queries/types/my-sessions"
import { useGraphQLWithToast } from "@/modules/toast/hooks"

/**
 * SessionsPage / devices feature container.
 *
 * Lists the current user's active login sessions (devices) and lets them log
 * out any device except the one making the request. Owns the page chrome
 * (breadcrumb + header) and the loading gate; revoking optimistically
 * revalidates the list. Mounted by `/profile/sessions`.
 */
export const SessionsPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const {
        data: sessions,
        isLoading,
        error,
        mutate,
    } = useQueryMySessionsSwr()
    const { trigger: triggerRevoke } = useMutateRevokeSessionSwr()
    const runGraphQL = useGraphQLWithToast()

    // the session id currently being revoked (drives the per-row spinner)
    const [revokingId, setRevokingId] = useState<string | null>(null)


    /** Revoke a device session, then revalidate the list. */
    const onRevoke = useCallback(
        async (sessionId: string) => {
            setRevokingId(sessionId)
            try {
                const ok = await runGraphQL(async () => {
                    // `triggerRevoke` returns the raw Apollo result; unwrap the
                    // standard `{ success, message }` payload for the toast helper.
                    const result = await triggerRevoke({ sessionId })
                    return result.data!.revokeSession
                })
                if (ok) {
                    // refresh so the logged-out device drops off the list
                    await mutate()
                }
            } finally {
                setRevokingId(null)
            }
        },
        [
            runGraphQL,
            triggerRevoke,
            mutate,
        ],
    )

    /** Format an ISO timestamp as `HH:mm MMM DD, YYYY` (24h time + short month). */
    const formatSeen = useCallback(
        (iso: string) => {
            // tolerate a bad/missing date rather than throwing in render
            const date = new Date(iso)
            if (Number.isNaN(date.getTime())) {
                return ""
            }
            const hh = String(date.getHours()).padStart(2, "0")
            const mm = String(date.getMinutes()).padStart(2, "0")
            const month = date.toLocaleString(locale, { month: "short" })
            const day = String(date.getDate()).padStart(2, "0")
            return `${hh}:${mm} ${month} ${day}, ${date.getFullYear()}`
        },
        [
            locale,
        ],
    )

    const sessionList = sessions ?? []

    const skeletonItems: Array<SurfaceCardListItem> = [0, 1, 2].map((row) => ({
        key: `skeleton-${row}`,
        content: () => (
            <div className="h-12">
                <StackH
                    gap={4}
                    align="center"
                    principle="content-row"
                    explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                    items={[
                        () => <Skeleton className="size-5 shrink-0 rounded" />,
                        () => (
                            <StackV
                                gap={3}
                                principle="sibling-stack"
                                explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                                classNames={["min-w-0", "flex-1"]}
                                items={[
                                    () => <Skeleton.Typography type="body-sm" width="1/2" />,
                                    () => <Skeleton className="h-3 w-1/3 rounded" />,
                                ]}
                            />
                        ),
                    ]}
                />
            </div>
        ),
    }))

    const sessionItems: Array<SurfaceCardListItem> = sessionList.map((session: LoginSession) => {
        const isMobile =
            session.deviceType === "mobile"
            || session.deviceType === "tablet"
        const DeviceIcon = isMobile ? DeviceMobileIcon : DesktopIcon
        const headline = [
            session.browser,
            session.os,
        ]
            .filter(Boolean)
            .join(" ΓÇó ") || t("sessions.unknownDevice")

        return {
            key: session.id,
            content: () => {
                const rowItems = [
                    () => <DeviceIcon aria-hidden focusable="false" className="size-5 shrink-0 text-accent-soft-foreground" />,
                    () => (
                        <div className="flex min-w-0 flex-1 flex-col gap-0">
                            <Cluster
                                gap={3}
                                align="center"
                                principle="chip-row"
                                explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                                items={[
                                    () => (
                                        <Typography type="body-sm" weight="medium" truncate>
                                            {headline}
                                        </Typography>
                                    ),
                                    ...(session.current
                                        ? [() => (
                                            <Chip color="accent" variant="soft" size="sm">
                                                <Chip.Label>{t("sessions.thisDevice")}</Chip.Label>
                                            </Chip>
                                        )]
                                        : []),
                                ]}
                            />
                            <div className="flex flex-wrap items-center gap-x-3 gap-y-2">
                                {session.location ? (
                                    <Typography type="body-xs" color="muted">{session.location}</Typography>
                                ) : null}
                                {session.ipAddress ? (
                                    <Typography type="body-xs" color="muted">{session.ipAddress}</Typography>
                                ) : null}
                                <Typography type="body-xs" color="muted">{formatSeen(session.lastSeenAt)}</Typography>
                            </div>
                        </div>
                    ),
                    ...(!session.current
                        ? [() => (
                            <Box principle="push-end" className="ml-auto shrink-0"
                                explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                                <Button
                                    variant="ghost"
                                    size="sm"
                                    className="text-danger-soft-foreground"
                                    isDisabled={revokingId === session.sessionId}
                                    onPress={() => onRevoke(session.sessionId)}
                                    aria-label={t("sessions.revoke")}
                                >
                                    {revokingId === session.sessionId ? (
                                        <Spinner color="current" size="sm" />
                                    ) : (
                                        <SignOutIcon aria-hidden focusable="false" className="size-5" />
                                    )}
                                    {t("sessions.revoke")}
                                </Button>
                            </Box>
                        )]
                        : []),
                ]

                return (
                    <StackH gap={4} align="center" principle="content-row"
                        explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                        items={rowItems} />
                )
            },
        }
    })

    return (
        <div className="flex flex-col gap-10">
            <PageHeader
                breadcrumb={<SettingsBreadcrumb current={t("sessions.title")} />}
                title={t("sessions.title")}
                description={t("sessions.subtitle")}
            />

            <AsyncContent
                isLoading={isLoading && !sessions}
                skeleton={<SurfaceCardList items={skeletonItems} />}
                isEmpty={sessionList.length === 0}
                emptyContent={{ title: t("sessions.empty") }}
                error={error}
                errorContent={{
                    title: t("sessions.empty"),
                    onRetry: () => { void mutate() },
                    retryLabel: t("common.retry"),
                }}
            >
                <SurfaceCardList items={sessionItems} />
            </AsyncContent>
        </div>
    )
}
